programs.sol:
"""A token-spelling detector, chiefly for 'self' and 'this'/'these'.

'self'/'Self' is strong; capitalization raises it, while opening delimiters,
indentation and repeated lowercase mentions can weaken it. Bare 'self' joined
to another word is weaker too. Demonstratives, selected translations of self,
and elf-like spellings are smaller signals. The URL stem www also responds.
Other tokens give zero: this captures the large lexical spikes, not all the
small background responses. In particular, a whole token 'myself' is ignored.
"""
import math

READS = ()

# Self-reference in Chinese, Japanese, German, Dutch and Russian.
SELF_WORDS = {
    '自我': 3.75, '自己': 0.87, '自分': 1.0,
    'selbst': 1.45, 'Selbst': 2.75, 'selber': 1.7,
    'zelf': 3.45, 'себя': 0.9, 'сам': 0.66,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        count, line, previous = 0, '', ''
    else:
        _, count, line, previous = carry
    token = prefix.token_strings[-1]
    clean = token.strip()
    word = clean.lstrip('([=:/<._*-$,"“>')
    value = 0.0
    if word in {'self', 'Self', 'SELF'}:
        capital = word != 'self'
        value = 6.9 if capital else 6.2
        if token.startswith('\t'):
            value -= 1.0
        if clean.startswith('('):
            value -= 1.2
        elif clean[:1] in '[<=*':
            value -= 2.2
        elif clean.startswith(':'):
            value -= 1.0
        if not capital:
            value -= 0.35 * math.log1p(count)
            if line.isspace():
                value -= 1.2
            if previous.strip() == '=':
                value -= 0.95
            if token == 'self' and previous.endswith('__('):
                value -= 2.1
            elif token == 'self' and previous[-1:].isalnum():
                value -= 2.7
        count += 1
    elif word.lower() in {'this', 'these'}:
        value = 0.9
        if word == 'this' and not token.startswith(' '):
            value = 1.2
        if token.startswith('\t'):
            value += 0.3
        if word == 'This' and clean == 'This' and token == clean:
            value = 1.04
    elif clean == 'www':
        value = 0.85 if token.startswith(' ') else 1.2
    elif clean in SELF_WORDS:
        value = SELF_WORDS[clean]
    elif clean == 'この':  # Japanese 'this'.
        value = 0.67
    elif clean.lower() in {'selves', 'selfish'}:
        value = 4.4 if clean.lower() == 'selves' else 2.5
    elif clean.lower() in {'elf', 'elves', 'shelf', 'shelves'}:
        if token == 'elf':
            value = 7.0 if previous.endswith('S') else 3.9
        else:
            value = 1.2 if clean.lower() == 'shelves' else 2.0
    # Keep only the unfinished line; escaped newlines count as line breaks too.
    line = (line + token).replace('\\n', '\n').rsplit('\n', 1)[-1][-100:]
    return (doc, count, line, token), float(value)

programs.luna:
"""Recognize the prominent demonstrative and self-reference word triggers."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip(" \t\r\n()=\"'`[]{}.,:;!?")
    word = word.casefold()
    if word == "self":
        return None, 5.0
    if word == "this":
        return None, 0.92
    if word == "these":
        return None, 0.84
    if word == "自己":
        return None, 0.76
    if word == "сам":
        return None, 0.66
    return None, 0.0

"""Mark selected descriptive modifiers after noun-phrase cues, plus “this section.”

The adjective-like cue is weak and negative; “section” was a recurring positive
exception in document-style text. Unmatched tokens get the neutral prediction.
"""

READS = ()

MODIFIERS = frozenset({
    "beautiful", "big", "critical", "different", "distinct", "early",
    "easy", "entirely", "extremely", "famous", "great", "important",
    "key", "large", "last", "major", "more", "most", "new", "other",
    "particular", "remarkable", "small", "special", "specific", "typical",
    "very", "weird", "大", "特定", "重要",
})

SETUP_WORDS = frozenset({
    "a", "an", "another", "any", "few", "many", "much", "one",
    "several", "some", "such", "that", "the", "these", "this", "those",
    "two", "three", "four", "how",
})


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    word = prefix.token_strings[-1].strip().lower()
    previous = prefix.token_strings[-2].strip().lower()
    if word == "section" and previous == "this":
        return None, 0.17
    if word in MODIFIERS and previous in SETUP_WORDS:
        return None, -0.17
    return None, 0.0

programs.sol:
"""Lexical note/annotation detector with an immediate following-token response.

The word 'note' gives the largest positive predictions. Its inflections,
annotation/reminder vocabulary and listed East Asian note markers are weaker.
Token fragments 'ote', 'otes' and 'oted' respond even outside the note family.
Case, spacing and attached punctuation alter some responses. Selected following
colons/connectives retain a smaller response. Unlisted tokens default to zero;
the split compound 'Foot' + 'note(s)' receives a smaller prediction.
"""
READS = ()

# Words and word fragments in the note/annotation family.
CUES = {
    'notes': 3.5, 'noted': 2.5, 'noting': 3.3,
    'footnote': 2.4, 'notebook': 1.7, 'notebooks': 1.6,
    'noteworthy': 1.1, 'keynote': 1.25,
    'ote': 2.1, 'otes': 1.2, 'oted': 0.7,
    'comment': 1.05, 'comments': 0.95, 'commented': 0.65,
    'annotation': 1.4, 'annotations': 1.2,
    'indicate': 0.7, 'indicates': 1.1, 'indicating': 1.2,
    'indicated': 0.6, 'indication': 0.55,
    'denote': 0.95, 'denotes': 0.8,
    'warning': 0.7, 'warnings': 0.5, 'notice': 0.2,
    'warn': 0.3, 'caution': 0.45, 'alert': 0.6,
    'tip': 0.4, 'tips': 0.35, 'hint': 0.95, 'hints': 0.8,
    'todo': 0.45, 'nb': 1.0, 'remark': 0.65, 'remarks': 0.9,
    'remember': 0.5, 'recall': 0.6, 'reminder': 0.85,
    'deprecated': 0.7,
    # Note, caution, explanation and reminder markers/expressions.
    '注': 3.5, '注意': 2.6, '要注意': 2.1, '请注意': 2.6,
    '注明': 2.8, '※': 2.8, 'ちなみに': 1.8,
    '说明': 1.15, '提醒': 1.4, '提示': 1.05,
}
CAPITAL_CUES = {
    'Notes': 3.1, 'NOTES': 3.4, 'COMMENT': 1.8, 'Comment': 1.25,
    'TODO': 1.2, 'Notice': 0.65, 'NOTICE': 0.7, 'Remember': 0.9,
}
DELIMITERS = '._-<>()[#/@\\'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = token.strip()
    plain = text.strip(DELIMITERS)
    word = plain.lower()
    prior = previous.strip().strip(DELIMITERS)
    prior_word = prior.lower()
    value = CAPITAL_CUES.get(plain, CUES.get(word, 0.0))
    if word == 'note':
        if plain != text:
            value = 5.3
        elif plain == 'NOTE':
            value = 6.7 if token.startswith(' ') else 9.0
        elif plain == 'Note':
            value = 7.0 if token.startswith(' ') else 7.2
        else:
            value = 5.35 if token.startswith(' ') else 5.65
    # 'Foot' + 'note(s)' is a compound, not a stand-alone note label.
    if plain in {'note', 'notes'} and prior == 'Foot':
        value = 3.5 if plain == 'note' else 2.65
    elif word.startswith('annotation') and text.startswith('.'):
        value = 2.2
    elif plain == 'warn' and not token.startswith(' '):
        value = 0.95

    if prior_word == 'note':
        capital = prior != prior_word
        if text == ':':
            if capital:
                value = 2.25 if previous.startswith(' ') else 2.8
            else:
                value = 1.05
        elif text.startswith(':'):
            value = 0.8 if '\n' in token else 1.2
        elif word in {'that', 'the', 'to', 'here'}:
            value += 1.2 if capital else 0.65
        elif word in {'of', 'on'}:
            value += 1.6 if word == 'of' else 1.0
    elif prior_word in {'notes', 'noted', 'noting'}:
        if word == 'that':
            value += 0.12 if prior_word == 'notes' else 0.45
        elif word in {'the', 'to', 'here', 'of', 'on'}:
            value += 0.5
    elif word == 'that' and prior_word in {'remember', 'recall', 'notice'}:
        value += 0.3 if prior == 'notice' else 0.6
    elif text == ':' and prior_word in {'warning', 'todo', 'deprecated', 'hint'}:
        value = 0.4 if prior == 'warning' else 0.75
    return (doc, token), float(value)

programs.luna:
"""Approximate sparse text-signposting: “note” is strongest, especially when
capitalized; comment and indicate/imply forms are weaker, and related cues get
small scores. “Out” only gets a score after a form of “point.”
"""
READS = ()

NOTE_WORDS = {"note", "notes"}
COMMENT_WORDS = {
    "comment", "comments", "commented", "commenting",
    "commentary", "commentaries",
}
INDICATE_WORDS = {
    "indicate", "indicates", "indicated", "indicating",
    "imply", "implies", "implied", "implying",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    previous, previous_doc = carry if carry is not None else ("", None)
    doc = prefix.document_ids[-1]
    if doc != previous_doc:
        previous = ""

    value = 0.0
    if word in NOTE_WORDS:
        value = 6.2 if raw[:1].isupper() else 5.5
    elif word in COMMENT_WORDS:
        value = 0.9
    elif word in INDICATE_WORDS:
        value = 0.9 if word.startswith("impli") else 1.0
    elif word in {"notice", "notices", "noted", "noting", "tip", "mind", "alert"}:
        value = 0.45
    elif word in {"caution", "warning", "prerequisite", "topic", "subject"}:
        value = 0.3
    elif word == "out" and previous in {"point", "points", "pointed", "pointing"}:
        value = 0.4

    return (word, doc), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:1156 -- a sparse, mostly lexical feature.

What it does, in plain terms: this MLP output direction responds to particular words,
and the response is mostly a property of the current word. Its activation is near zero
on most tokens, and a few word families move it clearly:

  * mystery and suspicion words (sinister, elusive, mysterious, suspicious, suspicion,
    secretly, vague, formidable, and the Chinese 邪 "evil") -> positive, about +0.25
  * praise and degree adjectives (good, great, well, high, serious, distinct) -> weakly
    positive, about +0.1
  * calamity and wreckage nouns (testament, mess, refugee, debris, aftermath, myriad,
    chaos, accident, disaster) -> negative, about -0.15
  * Java/Go error-handling identifiers (.java, assert, Println, Errorf,
    printStackTrace, RuntimeException) -> negative, about -0.1
  * the word " of" is also shifted by the word before it: after outcome nouns
    (result of, effect of, success of, failure of) it goes negative; after hint or
    suspicion nouns (suspicion of, hint of, notice of, title of) it goes positive.

Every other token predicts 0. The program reads only the newest one or two tokens, so
it is causal and needs no state between positions.
"""

READS = ()

MYSTERY = {
    "mysterious", "sinister", "elusive", "enigmatic", "ominous", "eerie", "suspicious",
    "suspicion", "vague", "secretly", "supernatural", "formidable", "unmistakable",
    "mystery", "cryptic", "邪",
}
DEGREE = {
    "good", "great", "well", "high", "higher", "greater", "distinct", "serious",
    "substantial", "dangerous", "exciting", "interesting",
}
CALAMITY = {
    "testament", "mess", "refugee", "refugees", "debris", "aftermath", "myriad",
    "chaos", "accident", "disaster", "catastrophe", "casualties", "failure", "victims",
}
CODE_ERROR = {
    ".java", "java", "/java", "assert", ".println", ".errorf", ".printstacktrace",
    "runtimeexception", "perror", ".junit", "illuminate",
}
OUTCOME = {
    "result", "results", "effect", "effects", "product", "products", "outcome",
    "outcomes", "success", "failure", "consequence", "consequences", "aftermath",
    "impact", "toll", "legacy",
}
HINT = {
    "suspicion", "hint", "notice", "memory", "memories", "feeling", "title", "topic",
    "tip", "sense", "reminiscent", "onset", "outbreak", "glimpse", "whiff", "trace",
    "suggestion", "echo", "vestige",
}
VALUES = [(MYSTERY, 0.25), (DEGREE, 0.1), (CALAMITY, -0.2), (CODE_ERROR, -0.12)]


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "of" and len(prefix) > 1:
        before = prefix.token_strings[-2].strip().lower()
        if before in OUTCOME:
            return carry, -0.12
        if before in HINT:
            return carry, 0.1
    for words, value in VALUES:
        if word in words:
            return carry, value
    return carry, 0.0

programs.luna:
"""Recognize perception/evidence words and a few familiar verb-particle phrases."""
READS = ()

PERCEPTION_STEMS = (
    "believ", "know", "think", "see", "hear", "look", "notice",
    "find", "suggest", "claim", "prove", "discover", "evident",
    "obvious", "apparen", "arent", "sound", "taste", "decid",
    "gather", "infer", "realiz", "perceiv", "understand", "persuad",
    "udden", "sudden", "somehow", "unfortun", "觉", "明显", "发现",
    "面容",
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip(".,;:!?()[]{}\"'")
    if any(stem in word for stem in PERCEPTION_STEMS):
        return None, 0.35

    recent = []
    doc = prefix.document_ids[-1]
    for i in range(max(0, prefix.position - 3), prefix.position):
        if prefix.document_ids[i] == doc:
            part = prefix.token_strings[i].strip().lower().strip(",.;:!?()[]{}\"'")
            recent.append(part)

    phrase = False
    if word == "to":
        phrase = any(p.startswith(("lead", "led")) for p in recent)
    elif word == "up":
        phrase = any(p.startswith(("add", "set")) for p in recent)
    elif word == "for":
        phrase = any(p.startswith("know") for p in recent)
    elif word == "into":
        phrase = any(p.startswith("turn") for p in recent)
    return None, 0.35 if phrase else 0.0

programs.sol:
"""Approximate three strong lexical responses, not a general semantic detector.

Look for 'let me/us' and "let's", the 'bed' part of testbed and /usr/local,
and dish/disk/pan words (especially Chinese 盘/盤). The last group fires on
word fragments and figurative uses too. Fixed levels estimated from training
examples leave the many weaker, scattered lexical responses at zero.
"""
READS = ()

# Characters denoting plates, basins, dishes, pots, bowls, and boards.
CONTAINER_CHARACTERS = {
    '盘': 5.6, '盤': 5.1, '盆': 2.05, '碟': 2.25,
    '锅': 0.95, '鍋': 0.75, '碗': 1.1, '皿': 0.65, '板': 0.38,
    '槃': 2.4, '磐': 1.5,  # Characters sharing the pan/plate form.
    '판': 0.8,  # Korean pan/board.
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    previous = carry[1] if same_document else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if previous.strip().lower() == 'let':
        if word in ('me', 'us'):
            value = 0.75 if word == 'me' else 0.7
        elif word in ("'s", '’s'):
            value = 1.19 if word == "'s" else 1.09
    if word == 'bed':
        value = 1.15 if previous.lower().endswith('test') else 0.26
    if word == '/local' and previous.lower().endswith('usr'):
        value = 0.70

    if word.lstrip('-_') in ('disc', 'disk'):
        value = 1.38 if token in (' disc', ' disk') else 1.12
    elif word == 'диск':
        value = 0.63
    elif word in ('discs', 'disks'):
        value = 1.0
    elif word == 'pan':
        value = 1.26 if token == ' pan' else 0.68
    elif word == 'pans':
        value = 1.0
    elif word in ('dish', 'dishes'):
        value = 0.88 if word == 'dish' else 0.77
    elif word in ('plate', 'bowl'):
        value = 0.90 if token.startswith(' ') and token.strip().islower() else 0.68
    elif word in ('plates', 'bowls'):
        value = 0.61
    elif word in ('tray', 'trays', 'skillet'):
        value = 1.1 if token in (' tray', ' skillet') else 0.73
    elif word in ('fork', 'forks'):
        value = 0.17
    elif word in ('oven', 'cooker', 'kitchen', 'dough', 'lunch'):
        value = 0.32 if token.startswith(' ') else 0.0
    elif word == 'salad':
        value = 0.53
    elif token in CONTAINER_CHARACTERS:
        value = CONTAINER_CHARACTERS[token]

    # Common compounds of the plate/disk character have different levels.
    if token == '盘':
        before = previous[-1:]
        if before == '磁':  # Magnetic disk.
            value = 2.6
        elif before == '吸':  # Suction cup.
            value = 3.9
        elif before in ('棋', '光'):  # Game board or optical disk.
            value = 4.8
    elif token in ('开盘', '盘点', '底盘'):
        value = 2.8  # Market opening, inventory, or chassis.
    elif token == '大盘':
        value = 4.0  # Overall market / large plate.
    elif token in ('楼盘', '收盘', '硬盘'):
        value = 1.0  # Property, closing market, or hard disk.

    # Occasionally a character is split across byte tokens: act on completion.
    if same_document and '\ufffd' in token:
        last = prefix.text_prefixes[-1][-1:]
        if last in CONTAINER_CHARACTERS:
            value = 7.2 if last == '盘' else CONTAINER_CHARACTERS[last]
    return (doc, token), value

programs.haiku:
"""Layer-0 MLP down_proj component 1158 (rare, token-driven).

It fires on a small family of words for flat kitchen/storage objects and discs
(dish, plate, pan, bowl, tray, disc/disk, and the Chinese for plate/pot), on the
word "bed" in paths such as "/testbed", and on the object of "Let" ("Let me",
"Let's", "Let us"). Otherwise it is silent.
"""

READS = ()

DISH_WORDS = {"dish", "dishes", "plate", "plates", "pan", "bowl", "tray",
              "disc", "disk", "discs", "disks", "oven", "salad", "basket", "pallet"}
CHINESE_DISHES = {"盘", "盤", "锅"}
LET_OBJECTS = {"me": 0.75, "us": 0.1, "'s": 1.0, "’s": 1.0}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if raw == "bed":
        return carry, 1.1
    if word in CHINESE_DISHES:
        return carry, 2.0
    if word in DISH_WORDS:
        return carry, 1.0
    if prev == "let" and word in LET_OBJECTS:
        return carry, LET_OBJECTS[word]
    return carry, 0.0

programs.sol:
"""Mostly a detector for singular forms of 'be', especially English 'is'.

The small lexicon includes common translations, and the neighboring word
'its'. Word boundaries keep suffixes such as the end of 'analysis' from
being read as 'is'. Capitalization and predicate names in code have their
own strengths. English 'is' and 'was' are additionally modulated by the
previous token's word class and spelling, and an early-document boost
that fades over about 30 tokens. State resets at each document boundary.
Everything else is nearly zero.
"""
import math

READS = ()

# Singular copulas in French, Spanish, Portuguese, Italian, German, Polish.
COPULAS = {
    'est': 1.50,
    'es': 1.15,
    'é': 1.25,
    'è': 1.40,
    'ist': 0.65,
    'jest': 0.85,
    'était': 1.00,
    'está': 1.20,
    'estava': 1.10,
    'foi': 0.75,
    'era': 0.45,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous = '' if fresh else carry[1]
    position = 0 if fresh else carry[2] + 1
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    spaced = token != token.lstrip()
    boundary = spaced or not previous or not previous[-1].isalpha()
    value = -0.002

    if lower in ('is', 'isn'):
        if word[0].isupper() and not word.isupper():
            value = 1.80 if boundary else 1.40
        elif word.isupper():
            value = 1.46 if boundary else 0.30
        else:
            value = 1.08 if spaced else 1.50 if boundary else -0.10
    elif lower in ('was', 'wasn'):
        value = 0.81 if spaced else 1.08
        if lower == 'wasn':
            value -= 0.16
    elif lower == 'its':
        value = 0.70 if boundary else 0.17
    elif lower in COPULAS:
        value = COPULAS[lower] if boundary else 0.10
    elif word in ('isinstance', 'instanceof', 'toBe'):
        value = 1.80 if word == 'isinstance' else 1.00
    elif word.startswith(('is', 'Is')) and len(word) > 2 and word[2].isupper():
        value = 1.25
    elif word.lstrip('._-/(').lower() == 'is':
        value = 2.35 if word.startswith('/') else 1.50

    if token in (' is', ' was'):
        value = 1.01 if token == ' is' else 0.77
        value += 0.35 * math.exp(-position / 30.0)
        prev_word = previous.strip()
        prev_lower = prev_word.lower()
        if prev_lower in ('it', 'this', 'that', 'he', 'she', 'i'):
            value -= 0.19
        elif prev_lower in ('what', 'how'):
            value -= 0.27
        elif prev_lower in ('which', 'who'):
            value += 0.08
        elif prev_lower == 'there':
            value += 0.23
        elif prev_word.isdigit():
            value += 0.20
        elif prev_word and not any(c.isalnum() for c in prev_word):
            value += 0.16
        if previous and previous[0].isalpha():
            value += 0.16
        if prev_word and prev_word[0].isupper() and not prev_word.isupper():
            value += 0.11

    return (doc, token, position), float(value)

programs.luna:
"""Approximate a lexical cue for English 'is'/'was' and related copulas.

Word boundaries help distinguish short verb spellings from pieces inside
other words. The possessive 'its' gets a smaller positive cue.
"""

READS = ()

PUNCTUATION = ".,/:;()[]{}<>\"'`-"
OTHER_COPULAS = {
    "est", "es", "è", "é", "ist", "jest", "está", "és", "был"
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    surface = token.strip()
    spelling = surface.strip(PUNCTUATION)
    word = spelling.casefold()
    title_case = surface[:1].isupper() and surface[1:].islower()
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
        left_boundary = not previous or not previous[-1].isalnum()
    else:
        left_boundary = False
    clear_word = (
        token[:1].isspace()
        or surface != surface.strip(PUNCTUATION)
        or title_case
        or left_boundary
    )

    if word in {"is", "isn"}:
        if not clear_word:
            return None, 0.2
        if word == "is" and spelling == "Is":
            return None, 1.75
        if word == "is" and spelling == "IS":
            return None, 1.3
        return None, 1.1
    if word == "was":
        return None, 0.8
    if word == "wasn":
        return None, 0.65 if clear_word else 0.2
    if word in OTHER_COPULAS:
        return None, 1.25 if clear_word else 0.25
    if word == "je":
        return None, 0.23 if clear_word else 0.0
    if word == "its":
