"""Approximate a negative response to name labels and lexical compounds.

Recognize NAME_ labels, Chinese compounds beginning with 名 (name/famous),
and continuations of form, string, word, and text. Technical compounds get
larger negative values than ordinary following words. Keep two previous
pieces to recognize a label's number; reset them at document boundaries.
This is a lexical approximation, not a prediction of every small response.
"""
READS = ()
FUNCTION_WORDS = frozenset('''a an the and or but of to in on at as from for
by with that this is are was were be been can could will would have has had
not it he she you we they my his her their our your'''.split())
# Famous works, famous people, and fame-related expressions.
FAME_COMPOUNDS = frozenset('作著言流门門医醫篇利')
NAME_COMPOUNDS = frozenset('曲画畫所模品城贵貴商头頭单單簿册冊录錄'
                          '目次气氣器号號堂宿物扬揚思')
FORM_PARTS = frozenset(('-control', '-group', '-horizontal'))
WORD_LAYOUT = frozenset(('-break', '-wrap', '-spacing'))


def response(previous, token):
    root = previous.strip(' \t\r\n()[]<>{/="\'.,')
    word = token.strip()
    joined = bool(token) and not token[0].isspace()
    if root == 'NAME' and word == '_':
        return -1.30 if previous.startswith(' ') else -0.85
    if root == 'username' and word == '_':
        return -0.70
    if root == '名' and word:
        if word[0] in FAME_COMPOUNDS:
            return -1.80
        if word[0] == '古':  # 名古屋 (Nagoya)
            return -1.20
        if word[0] in NAME_COMPOUNDS:
            return -0.90
        if '\u4e00' <= word[0] <= '\u9fff':
            return -0.18
    lower = root.lower()
    if lower == 'names' and joined and word in ('ake', 'paced'):
        return -1.06 if word == 'ake' else -0.55
    if lower == 'form':
        if word in FORM_PARTS:
            return -1.80
        if word.lower().lstrip('-') in ('factor', 'factors', 'data'):
            return -1.20
        if joined and word in ('work', 'ative'):
            return -1.35 if word == 'work' else -0.85
    if lower in ('string', 'strings'):
        if word.lower() == 'theory' or word == '.IsNullOrEmpty':
            return -0.95
        if word == '[]':
            return -0.38
        if word.startswith('.') and word[1:].isalpha():
            return -0.40 if root == 'String' else -0.20
    if lower == 'word' and word in WORD_LAYOUT:
        return -1.10
    if lower in ('name', 'names', 'form', 'string', 'strings', 'word', 'text'):
        if word.isalpha() and word.lower() not in FUNCTION_WORDS:
            if joined:
                return -0.27 if root == 'String' else -0.15
            return -0.075
        if word.startswith(('_', '-', '.')) and any(c.isalpha() for c in word):
            return -0.20
    return -0.0008


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    token = prefix.token_strings[-1]
    value = response(previous, token)
    if token.isdigit() and previous == '_' and before.strip() == 'NAME':
        value = -0.10
    return (doc, token, previous), float(value)

