programs.sol:
"""A partial local spelling model, dominated by what follows an i-like ending.

After an i-like ending, short word endings are positive; numbers and several
English auxiliaries are negative. Transliteration shares these spelling rules
across alphabets. Greek eta has an independent positive offset, and a short
i-like token at document start is also positive.
Only the preceding token is remembered; small token-specific background
activations and most longer fragments are deliberately left unexplained.
"""
import unicodedata

READS = ()

# Transliteration lets the same short-ending rules work across alphabets.
CYRILLIC = dict(zip(
    'абвгдежзийклмнопрстуфхцчшщыэюя',
    ('a','b','v','g','d','e','zh','z','i','y','k','l','m','n','o',
     'p','r','s','t','u','f','h','ts','ch','sh','sh','i','e','yu','ya')
))
CYRILLIC.update({'і':'i', 'ї':'yi', 'ы':'i'})
GREEK = dict(zip(
    'αβγδεζηθικλμνξοπρστυφχψω',
    ('a','b','g','d','e','z','i','th','i','k','l','m','n','x','o',
     'p','r','s','t','u','f','h','ps','o')
))
GREEK['ς'] = 's'


def kana_sound(char):
    """Unicode kana names give the syllables: MI, RI, NI, SI, etc."""
    name = unicodedata.name(char, '')
    if name.startswith(('KATAKANA LETTER ', 'HIRAGANA LETTER ')):
        return name.rsplit(' ', 1)[-1].lower()
    return ''


def romanize(text):
    out = []
    for char in text.lower():
        base = unicodedata.normalize('NFD', char)[0]
        if 'a' <= base <= 'z':
            out.append(base)
        elif char in CYRILLIC:
            out.append(CYRILLIC[char])
        elif base in CYRILLIC:
            out.append(CYRILLIC[base])
        elif base in GREEK:
            out.append(GREEK[base])
        elif kana_sound(char):
            out.append(kana_sound(char))
        else:
            return ''
    return ''.join(out)


def i_ending(text):
    if not text:
        return False
    char = text[-1]
    letters = ''.join(c for c in unicodedata.normalize('NFKD', char.lower())
                      if not unicodedata.combining(c))
    base = letters[-1] if letters else ''
    if base and base in 'iıиіїыιηیي':
        return True
    if kana_sound(char).endswith('i'):
        return True
    code = ord(char) - 0xAC00
    return 0 <= code < 11172 and code % 28 == 0 and (code // 28) % 21 == 20


# Short spelling continuations, including -iya/-iyu, -ion, -ios and -ius.
# Transliteration shares these rules across alphabets.
NASAL_VOWEL_ENDINGS = {'na', 'ni', 'nu', 'ny', 'em', 'en', 'ey', 'am', 'an'}
OTHER_ENDINGS = {'est', 'ens', 'ias', 'ode', 'odes', 'ini', 'que', 'ques'}
AUXILIARIES = {
    'can':-0.65, 'cannot':-0.4, 'could':-0.3, 'would':-0.22,
    'will':-0.27, 'have':-0.26, 'must':-0.7, 'may':-0.46,
}


def response(text):
    if text in ('η', 'ή', 'Η', 'Ή'):
        return 0.0  # The independent eta response is added separately.
    if text in ('ω', 'ώ'):
        return -0.2
    if text in ('ε', 'έ', 'Έ'):
        return -0.65
    if text == 'ό':
        return 0.1
    if text == '/O':
        return 1.5  # I/O notation.
    if text.startswith(' '):
        word = text.strip().lower()
        if word in ('think', 'thank'):
            return 0.75
        if word in ('thought', 'that'):
            return 0.35
        if word == 'like':
            return -0.7
        return AUXILIARIES.get(word, 0.0)
    if text.isdigit():
        return -0.5
    if text.startswith('ック'):
        return 1.2  # Japanese geminate velar consonant.
    if text.startswith('ッ'):
        return 0.2
    if text.startswith('ン'):
        return 0.65  # Japanese syllable-final nasal.
    if len(text) == 1:
        code = ord(text) - 0xAC00
        if (0 <= code < 11172 and code // 588 == 11
                and (code // 28) % 21 in (0, 8) and code % 28 in (0, 4)):
            return 1.3  # Korean a/o, optionally followed by n.
        if '\u0600' <= text <= '\u06ff' and text.isalpha():
            return 1.2 if text == 'ا' else 0.7
    fragment = romanize(text)
    if not fragment:
        return 0.0
    if fragment == 'une':
        return 2.8
    if fragment.startswith('y') and len(fragment) <= 3:
        return 1.15
    if fragment in ('on', 'ona'):
        return 1.5
    if (fragment[0] == 'o'
            and fragment[1:] in ('', 's', 'n', 't', 'c', 'b', 'm', 'r', 'u')
            or fragment[0] == 'u' and fragment[1:] in ('', 'm', 'n', 's')):
        return 1.05
    if fragment in NASAL_VOWEL_ENDINGS:
        return 0.8
    if fragment in OTHER_ENDINGS:
        return 0.7
    if fragment.startswith('olog'):
        return 0.45
    sound = kana_sound(text) if len(text) == 1 else ''
    if sound and sound[0] in 'knrs':
        return 0.6
    if len(fragment) == 1:
        return 0.8 if fragment == 'i' else 0.4
    if len(fragment) == 2:
        if fragment in ('ch', 'ke', 'it', 'is', 'ns'):
            return 0.9
        return 0.0
    if text[:1].isupper():
        return -0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    new_document = carry is None or carry[0] != doc
    # A UTF-8 character can be split across tokens; use its completed spelling.
    if text == '\ufffd' and not new_document:
        completed = prefix.text_prefixes[-1][-1:]
        if completed and completed != '\ufffd':
            text = completed
    previous = '' if new_document else carry[1]
    value = 0.7 if text in ('η', 'ή', 'Η', 'Ή') else 0.0
    if i_ending(previous):
        value += response(text)
    elif new_document and len(text.strip()) <= 2 and i_ending(text):
        value = 0.8
    return (doc, text), value

"""Detect vertical-bar punctuation, with a fading memory of repeated bars.

An isolated bar gives about 1.4. Nearby repetitions weaken that response;
the memory fades over roughly twenty tokens and resets between documents.
Bars fused with newlines and double bars are weaker than ordinary bars.
Some architectural words give a negative response, especially Chinese
characters naming pavilions and other roofed structures.
"""
import math

READS = ()

# Architectural vocabulary; these are words, not tokenizer IDs.
PAVILIONS = {"阁": -2.0, "閣": -1.4, "亭": -1.5, "轩": -0.9}
STRUCTURES = frozenset("楼樓屋坊塔堂")
TOWER_WORDS = frozenset(("tower", "towers", "lighthouse", "dome"))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        recent_bars = 0.0
    else:
        recent_bars = carry[1] * 0.9512
    token = prefix.token_strings[-1]
    value = 0.0
    if '|' in token and not token.startswith('<|'):
        if '||' in token:
            value = 0.16
        else:
            value = max(0.2, 1.4 - 0.49 * math.log1p(recent_bars))
            if '\n' in token:
                value *= 0.40 if token.count('\n') == 1 else 0.25
            elif any(char in token for char in '=$.'):
                value *= 0.18
            elif '-' in token:
                value *= 0.60
            recent_bars += 1.0
    elif '│' in token:
        value = 0.50
    elif '∣' in token:
        value = 0.35
    elif token in PAVILIONS:
        value = PAVILIONS[token]
    elif token in STRUCTURES:
        value = -0.45
    elif token.strip().lower() in TOWER_WORDS:
        value = -0.35
    return (document, recent_bars), float(value)

