DETERMINER = {" a": 1.0, " an": 1.2, " one": 1.1, " two": 0.6}
# Prepositions that open a noun phrase object, and the strongest of them.
FOR_OF = {" for", " of"}
PREPOSITIONS = {" in", " to", " from", " on", " at", " by", " into", " over", " under", " through", " during", " that", " such", " if", " When", " If", " when"}
# Action verbs that take an object.
VERBS = {" make", " makes", " making", " made", " create", " creates", " creating", " use", " uses", " using",
         " do", " does", " take", " takes", " taking", " choose", " detect", " define", " provide", " provides",
         " gives", " give", " develop", " offers", " offer", " build", " building", " form", " forms", " forming",
         " cause", " get", " become", " represent", " consider", " pass", " need", " see", " implement",
         " design", " write", " generate", " produce", " perform"}
WITH = {" with"}
# Copulas, conjunctions and punctuation: the article here is a predicate or a coordinated item.
LINKS = {" is", " was", " were", " are", " be", " been", " being", " am", " has", " had", " having",
         " and", " or", " also", " as", ",", ".", ":", ";", "(", " -", " +", " ="}
OTHER = 0.5
VERB = 1.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    scale = DETERMINER.get(word, 0.0)
    if scale == 0.0 or len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    before = prefix.token_strings[-2]
    if before in FOR_OF:
        gain = 2.0
    elif before in PREPOSITIONS:
        gain = 1.1
    elif before in VERBS:
        gain = VERB
    elif before in WITH:
        gain = 0.3
    elif before in LINKS:
        gain = 0.0
    else:
        gain = OTHER
    return carry, float(scale * gain)

