"""A short-letter-fragment approximation, mostly with negative responses.

The strongest cases are Arabic إ, Cyrillic Э/э, and circumflex î/Î.
Other selected foreign letters, vowel marks, and short vowel-bearing
syllables have weaker responses. Spaces matter; Arabic clitics soften
some responses. Broken Unicode tokens use recently seen script and a
few completed vowel spellings. Everything else is near zero. This does
not model the component's miscellaneous whole-word responses.
"""
import unicodedata
from functools import lru_cache

READS = ()

# Bare letters: (without a leading space, with a leading space).
LETTERS = {
    'Э': (-3.6, -3.3),
    'э': (-3.15, -4.05),
    'î': (-2.2, -2.05),
    'Î': (-2.5, -2.8),
    'é': (-0.11, -1.1),
    'É': (-0.42, -0.71),
    'ö': (-0.22, -0.89),
    'Ö': (-0.47, -0.97),
    'İ': (-0.60, -1.75),
    'đ': (-1.0, -1.5),
    'Đ': (-0.88, -0.95),
    'И': (-0.51, -0.68),
    'О': (-0.1, -0.42),
    'о': (0.0, -0.15),
    'α': (-0.13, -0.22),
    'エ': (-0.52, -0.52),
    '에': (-0.35, -0.4),
    'อ': (-1.0, -1.1),
    '伊': (-1.1, -1.1),
    '埃': (-0.93, -0.93),
    '阿': (-0.58, -0.58),
    'E': (-0.075, -0.135),
}
ALIF = {
    'إ': (-5.7, -7.15),
    'ا': (-0.39, -2.18),
    'أ': (-1.19, -1.24),
    'آ': (-0.83, -0.79),
}
ARABIC_ONSETS = {'ال': -0.72, 'است': -1.3, 'الت': -0.66, 'ت': -0.87}
# Polytonic Greek vowels / Arabic tanwin completed by a byte fragment.
COMPLETED_VOWELS = {
    'ἐ': -1.95, 'ἄ': -1.85,
    'ἀ': -0.95, 'ἔ': -0.95, 'ἰ': -0.95, 'Ἰ': -0.95,
    'ٍ': -1.97, 'ٌ': -1.27,
}


@lru_cache(maxsize=8192)
def letter_response(token):
    s = token.strip()
    spaced = int(token.startswith(' '))
    if s in LETTERS:
        return LETTERS[s][spaced]
    if s in ALIF:
        return ALIF[s][spaced]
    if s in {'ِ', 'ُ'}:  # kasra and damma: short vowel marks
        return -1.8
    if s in {'َ', 'ً'}:  # fatha and fathatan
        return -0.64

    # wa-, bi-, li-, fa-, and the definite article al-.
    rest, scale = s, 1.0
    if len(rest) > 1 and rest[0] in 'وبلف':
        rest, scale = rest[1:], 0.6
    if len(rest) > 2 and rest.startswith('ال'):
        rest, scale = rest[2:], scale * 0.75
    if rest in ALIF and rest != s and rest != 'ا':
        return scale * ALIF[rest][spaced]
    if spaced and s in ARABIC_ONSETS:
        return ARABIC_ONSETS[s]
    if s.startswith('إ') and len(s) == 2:
        return -1.8 if s[1] == 'ن' else -0.65
    if spaced and s.startswith('الإ') and len(s) > 3:
        return -1.4 if len(s) <= 5 else -0.2

    if spaced and s.lower() == 'ин':
        return -1.08
    if spaced and s.lower() in {'ис', 'исп'}:
        return -0.5
    if spaced and s.lower() == 'из':
        return -0.29
    if s.lower().startswith('э') and len(s) >= 2:
        return -0.9 if len(s) == 2 else (-0.3 if spaced else 0.0)
    if s == 'エン':
        return -0.43
    if s in {"'é", '’é'}:
        return -1.0
    if spaced and s in {'dé', 'lé', 'être'}:
        return -0.7
    return 0.0


@lru_cache(maxsize=8192)
def writing_system(text):
    for char in reversed(text):
        if char.isascii() or char == '�':
            continue
        name = unicodedata.name(char, '')
        for script in ('GREEK', 'LATIN', 'CYRILLIC', 'ARABIC', 'TAMIL',
                       'GURMUKHI', 'HIRAGANA', 'KATAKANA', 'HANGUL', 'CJK'):
            if script in name:
                return script
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    if new_document:
        carry = (doc, None, 100)
    _, script, age = carry
    token = prefix.token_strings[-1]
    text = token
    value = letter_response(token)
    if token in {'�', ' �'}:
        # Do not join an incomplete character across document boundaries.
        text = '�' if new_document else prefix.text_prefixes[-1][-1]
        value = -0.14 if token.startswith(' ') else -0.04
        if token == '�' and text in COMPLETED_VOWELS:
            value = COMPLETED_VOWELS[text]
        elif age <= 12:
            if token.startswith(' '):
                value = {'GREEK': -0.67, 'LATIN': -0.39,
                         'CYRILLIC': -0.31, 'ARABIC': -0.62,
                         'TAMIL': -0.78, 'GURMUKHI': -0.8}.get(script, 0.0)
            else:
                value = {'GREEK': -0.19, 'ARABIC': -0.53,
                         'LATIN': -0.085}.get(script, -0.025)
    seen = writing_system(text)
    script, age = (seen, 0) if seen else (script, age + 1)
    return (doc, script, age), float(value)

