"""layers.0.mlp.down_proj:1169 -- a sparse, mostly-negative response to bare
"vowel-letter" fragments of Arabic and Cyrillic words.

What it does: looks at the current token only. Most tokens get 0. The component
is strongly negative when the token is a bare letter that starts a foreign word
or word piece:
  - the Arabic letter إ (alef with hamza below): about -6.5 alone, -4 when it ends
    a token (e.g. " الإ"), -1 when it sits inside a token (e.g. " إن");
  - the Cyrillic letter э/Э: about -3.5 alone, -0.5 inside a word (e.g. " это");
  - Arabic أ (-1.2) and plain ا (-2.2 after a space, -0.5 otherwise);
  - accented Latin letters at the start of a word (" é" -1, " đ", " î", " İ");
  - Unicode replacement characters (half of a multi-byte character), a little
    negative; more so after a space.
Arabic diacritics and a space-led bare Arabic letter get small negatives.

Why: these are the tokens that carry the component's large activations (the
strongest is ~-7). Everything else, including ordinary English and CJK tokens, is
near 0 with small noise the program does not model.
"""
READS = ()

HAMZA_BELOW = "إ"       # إ
HAMZA_ABOVE = "أ"       # أ
PLAIN_ALEF = "ا"        # ا
E_REVERSED = "эЭ"  # э, Э
ACCENTED_LATIN = "éÉîÎöđĐİ"  # é É î Î ö đ Đ İ
ARABIC_MARKS = "ًٌٍَُِّ"  # tanween, harakat, shadda


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]   # the newest token, decoded alone
    s = raw.strip()
    lead = raw[:1] == " "            # token begins a new word
    if s == HAMZA_BELOW:
        return None, -6.5
    if s.endswith(HAMZA_BELOW):
        return None, -4.0
    if HAMZA_BELOW in s:
        return None, -1.0
    if s == PLAIN_ALEF:
        return None, -2.2 if lead else -0.5
    if s in ("э", "Э"):
        return None, -3.5
    if "э" in s or "Э" in s:
        return None, -0.5
    if s == HAMZA_ABOVE:
        return None, -1.2
    if HAMZA_ABOVE in s:
        return None, -0.5
    if lead and len(s) == 1 and s in ACCENTED_LATIN:
        return None, -1.0
    if len(s) == 1 and s in ARABIC_MARKS:
        return None, -0.5
    if lead and len(s) == 1 and "؀" <= s <= "ۿ":
        return None, -0.4
    if "�" in raw:
        return None, -0.16 if lead else -0.05
    return None, 0.0

