"""Estimate the response to commas used as code/list separators.

A bare comma gets a pulse that decreases with token distance from the nearest
unmatched opening bracket. Function calls and generic type lists decay more
slowly; type-checking calls are weaker. Import lines and identifier-shaped
items supply additional cues. Bare commas following backslashes are suppressed.
Fused comma/closing-punctuation tokens and adjacent index brackets have small
fixed rules. Everything else is silent. State resets at document boundaries.
"""
import re

READS = ()
OPENING_FOR = {')': '(', ']': '[', '}': '{', '>': '<'}
MATH_MARKS = re.compile(r'[=+*/^\\]')


IMPORT_LINE = re.compile(
    r"(?:^|\\n|[\"'])\s*(?:\d+\s+)?[+-]?\s*"
    r"(?:from\s+[.\w]+\s+)?import\s"
    r"|\buse\s+\w+(?:::\w+)*::")
GENERIC_TYPE = re.compile(
    r'(?:[A-Z]\w+|::\w+|template\s*|\b(?:fn|function)\s+\w+)$')
TYPE_CHECKS = frozenset({'isinstance', 'issubclass'})

# Responses for comma tokens fused with a closing character:
# (same-line, newline). These are punctuation classes, not token IDs.
COMMA_AFTER = {
    '"': (0.85, 0.44),
    "'": (0.85, 0.44),
    ')': (0.28, 0.30),
    ']': (0.68, 0.47),
    '}': (0.43, 0.34),
    '>': (0.73, 0.73),
    '`': (0.50, 0.50),
    '_': (1.34, 1.34),
    '.': (0.12, 0.12),
    '%': (0.12, 0.12),
}


def list_pulse(state):
    if IMPORT_LINE.search(state['line']):
        return 2.3 if state['line_commas'] == 0 else 1.8
    frames = state['frames']
    if not frames:
        return 0.08 if MATH_MARKS.search(state['recent']) else 0.0
    kind, opened, _, _ = frames[-1]
    distance = state['position'] - opened
    if any(call for _, _, call, _ in frames):
        if any(check for _, _, _, check in frames):
            return 0.85 / (1.0 + distance / 20.0) ** 0.6
        return 2.65 / (1.0 + distance / 3.0) ** 0.6
    if any(kind == '{' for kind, _, _, _ in frames):
        return 0.55 + 1.8 / (1.0 + distance / 3.0) ** 1.2
    height = 2.0 if kind == '(' else 2.8
    return height / (1.0 + distance / 3.0) ** 1.2


def bare_comma(state):
    if state['line'].endswith('\\'):
        return 0.0  # LaTeX's \, is spacing, not a list separator.
    value = list_pulse(state)
    match = re.search(r'([A-Za-z_][A-Za-z_0-9]*|[0-9]+)$', state['line'])
    word = match[1] if match else ''
    if '_' in word:
        value = max(value, 0.9)
    elif re.search(r'[a-z][A-Z]', word):
        value = max(value, 0.65)
    if word.isdigit():
        value = max(value, 0.06) * 0.92
    return value


def punctuation_value(text, state):
    if ',' not in text:
        return 0.33 if '][' in text else 0.0
    if text.strip() == ',':
        if '\n\n' in text:
            return 0.02
        if '\r\n' in text:
            return 0.88
        if '\n' in text:
            return 0.57
        return bare_comma(state) * (0.7 if text.startswith(' ') else 1.0)
    if text.startswith(','):
        following = text[1:]
        if following.isalpha():
            return 0.42 if len(following) == 1 else 0.29
        if following.startswith('\\'):
            return 0.57
        if following.startswith(('"', "'")):
            return -0.09
        return 0.0
    if not text.rstrip().endswith(','):
        return 0.2
    before = text.rstrip()[:-1]
    newline = '\n' in text
    if before.endswith(('()', '[]', '{}')):
        return 0.7 if newline else 1.3
    return COMMA_AFTER.get(before[-1:], (0.43, 0.43))[newline]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry['doc'] != doc:
        carry = dict(doc=doc, position=0, frames=[], line='',
                     recent='', line_commas=0)
    text = prefix.token_strings[-1]
    value = punctuation_value(text, carry)
    for char in text:
        if char == 'n' and carry['line'].endswith('\\'):
            carry['line'] = ''
            carry['line_commas'] = 0
            continue  # A written \n also starts a new line of embedded code.
        generic = char == '<' and GENERIC_TYPE.search(carry['line'])
        if char in '([{' or generic:
            call = generic or (char == '(' and bool(re.search(
                r'[A-Za-z0-9_]$|(?:=|return|constructor)\s*$',
                carry['line'])))
            name = re.search(r'([A-Za-z_]\w*)\s*$', carry['line'])
            check = bool(name and name[1] in TYPE_CHECKS)
            carry['frames'].append((char, carry['position'], bool(call), check))
        elif char in ')]}>':
            opening = OPENING_FOR[char]
            for i in range(len(carry['frames']) - 1, -1, -1):
                if carry['frames'][i][0] == opening:
                    del carry['frames'][i:]
                    break
        elif char == ',':
            carry['line_commas'] += 1
        if char == '\n':
            carry['line_commas'] = 0
            carry['line'] = ''
        else:
            carry['line'] = (carry['line'] + char)[-300:]
    carry['recent'] = (carry['recent'] + text)[-160:]
    carry['position'] += 1
    return carry, float(value)

programs.haiku:
"""Layer-0 MLP unit 1170 (down_proj): a comma that separates items inside brackets.

What it does: it reads the text as a stream and keeps track of which brackets are open,
( [ { and when they close, within each document. On a comma that sits inside an open
bracket it predicts a strong activation, strongest for the first comma of a bracket
(a function's first argument, the first element of a list or tuple, a parenthesised
parameter list) and weaker for later commas. Commas after a prose word, as in "et al.,"
or "however,", get half that. Commas outside any bracket, and every other token, get 0.

Why: the unit's output is largest on commas in code-like lists (f(self, x), [a, b],
SELECT a,b, import x, y) and near zero on commas in running English.
"""

READS = ()

OPENERS = "([{"
CLOSERS = ")]}"


def _is_prose_word(token):
    # A space followed by letters only, e.g. " however", " Smith".
    return token[:1] == " " and token[1:].isalpha()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        stack = []  # one entry per open bracket: how many commas it has had so far
    else:
        stack = list(carry[1])
    token = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == doc
    prev = prefix.token_strings[-2] if same_doc else ""
    value = 0.0
    done = False
    for ch in token:
        if ch in OPENERS:
            stack.append(0)
        elif ch in CLOSERS:
            if stack:
                stack.pop()
        elif ch == ",":
            if stack and not done:
                value = 1.2 if stack[-1] == 0 else 0.6
                if _is_prose_word(prev):
                    value *= 0.5
                done = True
            if stack:
                stack[-1] += 1
    return (doc, stack), float(value)

programs.luna:
"""Give comma punctuation a small positive score, slightly favoring compact syntax."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "," not in token:
        return None, 0.0
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]
    return None, 0.20 if previous[:1].isspace() else 0.24

programs.sol:
"""A small negation-and-formatting proxy for a weak mixed component.

Some English expressions shift upward after a recent negative cue. Keep
that shift, positive offsets for cannot/beyond/shall, negative honorific
offsets, and a few formatting markers. A twelve-token window approximates
recent negation; it is not a syntactic scope parser. Most of the component's
unrelated lexical and contextual variation remains unmodeled.
"""

READS = ()
NEGATORS = frozenset(
    "no not never none nothing neither nor cannot without unable impossible"
    .split()
) | {"n't", "'t", "’t"}

# Training means without a recent negative cue.
POLARITY_WORDS = {
    " any": -0.026,
    " ever": -0.065,
    " other": 0.040,
    " only": -0.008,
    " good": -0.002,
    " before": -0.017,
    " except": 0.008,
    " need": 0.002,
    " more": 0.021,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    age = 13 if carry is None or carry[0] != document else carry[1]
    value = POLARITY_WORDS.get(token, 0.001)
    if token in POLARITY_WORDS and age <= 12:
        value += 0.042
    if token == " cannot":
        value = 0.138
    elif token == " beyond":
        value = 0.138
    elif token == " shall":
        value = 0.076
    elif token in (" Mr", " Mrs", " Dr"):
        value = -0.097
    elif token == "  ":
        value = 0.027
    elif token == "\\t":
        value = 0.033
    elif token == "%":
        value = -0.040
    elif token == "__":
        value = -0.033
    elif token == "</think>":
        value = 0.065
    elif token == "</tool_call>":
        value = 0.055
    elif token == "<|im_end|>":
        value = -0.043
    word = token.strip().lower()
    age = 1 if word in NEGATORS else min(age + 1, 13)
    return (document, age), float(value)

programs.haiku:
"""Diffuse word-level feature: small signed nudges on a few word classes.

Layer-0 MLP feature with no clear concept. The only consistent signals found:
- "cannot" and "other"/"more"/"different"/"same" push it up;
- "lack", "few", "none", "either", "both", "many" push it down;
- " of" after "lack" or "example" is negative; after quantifiers ("any", "each", "none") positive.
Everything else predicts 0.
"""
READS = ()

COMPARATIVE_UP = {" other", " others", " more", " different", " same", " an", " her", " your", " its"}
QUANTIFIER_DOWN = {" few", " none", " either", " both", " many", " another", " never", " those", " one", " two", " kind"}
OF_NEG_PREV = {" lack", " example", " kind", " experience"}
OF_POS_PREV = {" any", " each", " none", " regardless", " None", " Each", " any"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if word == " cannot":
        value = 0.14
    elif word == " lack":
        value = -0.10
    elif word == " of" and prev in OF_NEG_PREV:
        value = -0.12
    elif word == " of" and prev in OF_POS_PREV:
        value = 0.12
    elif word in COMPARATIVE_UP:
        value = 0.03
    elif word in QUANTIFIER_DOWN:
        value = -0.03
    else:
        value = 0.0
    return carry, value

programs.luna:
"""A small proxy: capitalized word starts and the temporal word 'after' get a negative score."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.strip().lower() == "after":
        return None, -0.08

    first_letter = next((char for char in token if char.isalpha()), "")
    if first_letter and first_letter.isupper():
        return None, -0.04
    return None, 0.0

programs.sol:
"""Approximate two negative responses: semicolons and prime-like spellings.
Semicolons joining prose clauses are strong; code-like lines weaken them, and
HTML entity terminators or newline-fused semicolons are mostly silent.
'Prime' is the strongest word response. The ending fragments ime/imes and
consonant-cluster, silent-e spellings (crime, grade, stroke, etc.) also respond.
Other tokens are left at zero. These are spelling heuristics, not a test for
prime numbers; finer differences among individual words are omitted.
"""
import re

READS = ()
ENTITY = re.compile(r'&(?:#[xX]?[0-9a-fA-F]{1,8}|[A-Za-z]{1,12})$')
SILENT_E = re.compile(
    r'([bcdfghjklmnpqrstvwxyz]{2,})([aeiou][bcdfghjklmnpqrstvwxyz]e)(s?)$'
)
# Responses by spelling ending, shared across words with that ending.
ENDING_RESPONSE = {
    'ime': -1.20,
    'ade': -0.48,
    'ave': -0.67,
    'ale': -0.26,
    'ike': -0.46,
    'ipe': -0.63,
    'oke': -0.42,
    'one': -0.24,
    'ice': -0.16,
    'ute': -0.36,
}


def semicolon(token, before):
    mark = token.strip()
    if '\n' in token or '\r' in token:
        return -0.4 if '；' in token else -0.03 if mark == ';' else 0.03
    if mark in (';', '；'):
        if ENTITY.search(before):
            return 0.0
        if mark == '；':
            return -0.72
        if before.endswith('\\'):
            return -0.59
        line = before.rsplit('\n', 1)[-1]
        if '=' in line or '{' in before[-120:]:
            return -0.38
        if 'test result:' in before or 'filtered out' in before:
            return -0.50
        if line.startswith(('    ', '\t')) or '_' in line:
            return -0.64
        return -0.78
    if mark.endswith(';'):
        if mark[0] in '.%“”‘’':
            return -0.74
        if mark in (');', '];', '};') and not token.startswith(' '):
            return -0.41
        if mark in ('";', "';"):
            return -0.34
        return -0.15
    return -0.23 if '\\' in token else -0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_.').lower()
    value = 0.0
    if ';' in token or '；' in token:
        value = semicolon(token, before)
    elif word == 'prime':
        if token == 'prime' and before.endswith('\\'):
            value = -0.85  # LaTeX's prime symbol, rather than a complete word.
        else:
            value = -2.52 if token[:1].isspace() else -2.2
    elif word == 'primes':
        value = -1.63
    elif word in ('ime', 'imes'):
        value = -0.95
        if before.lower().endswith(('pr', 'cr', 'sl', 'gr', 'ch')):
            value = -1.65
        elif word == 'imes' and before.endswith('\\t'):
            value = -0.15  # The multiplication command, \\times.
    else:
        match = SILENT_E.fullmatch(word)
        if match and match[1] not in ('th', 'sh', 'ph', 'ch', 'wh'):
            value = ENDING_RESPONSE.get(match[2], -0.04)
            if match[3] and match[2] != 'ime':
                value *= 0.65
    return (doc, (before + token)[-240:]), value

programs.luna:
"""A small text-shape proxy for this sparse component.

Chat delimiters and their speaker labels have distinctive responses. For
ordinary pieces, the prediction rises with visible length and gets a small
extra for alphabetic characters outside ASCII; contextual variation remains.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_document = (
        len(prefix.document_ids) > 1
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    )

    if token == "<|im_end|>":
        return None, 3.1
    if token == "<|im_start|>":
        return None, 1.65
    if token == "<tool_response>":
        return None, 2.5
    if (
        same_document
        and prefix.token_strings[-2] == "<|im_start|>"
        and token in {"assistant", "user"}
    ):
        return None, -0.12

    value = -0.016 + 0.012 * min(len(token.strip()), 12)
    if any(ch.isalpha() and ord(ch) > 127 for ch in token):
        value += 0.04
    return None, value

programs.sol:
"""Approximate the component's prospective-existence and new-entity signal.

It recognizes nonfinite 'be', forms of 'become', and 'new'.  Indefinite
articles are stronger after creation or acquisition verbs than after
prepositions or descriptions.  Modal verbs and 'a new' adjust the strength.
An 80-character suffix joins split words and resets between documents.
Other, weaker lexical responses are omitted.
"""
import re

READS = ()
WORDS = re.compile(r"[^\W\d_]+(?:['’]\w+)?")
LAST = re.compile(r"([^\W\d_]+(?:['’]\w+)?)\s*$")
CREATION = set('create build write start make add generate design develop '
               'establish launch prepare implement invent compose'.split())
ACQUISITION = set('have get find take provide offer obtain acquire buy '
                  'choose pick select'.split())
DESIRE = set('need want wish hope aim intend'.split())
IRREGULAR = dict(made='make', built='build', wrote='write', got='get',
                 found='find', took='take', taken='take', had='have')
ROOTS = CREATION | ACQUISITION | DESIRE


def root(word):
    if word in IRREGULAR:
        return IRREGULAR[word]
    for ending in ('ing', 'ed', 'es', 's'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            for candidate in (stem, stem + 'e', stem[:-1]):
                if candidate in ROOTS:
                    return candidate
    return word


def article(previous):
    lemma = root(previous)
    if lemma in CREATION:
        return 1.55 - (0.3 if previous.endswith(('ed', 's')) else 0.0)
    if lemma in DESIRE:
        return 1.2
    if lemma in ACQUISITION:
        return 0.7
    if previous == 'has':
        return 0.47
    if previous in {'become', 'became', 'becoming'}:
        return 1.3
    if previous in {'be', 'been', 'being', 'give', 'bring', 'hold', 'do', 'out', 'up'}:
        return 0.42
    if previous in {'for', 'without'}:
        return 0.35
    if previous in {'by', 'from', 'than', 'within'}:
        return -0.25
    if previous in {'in', 'on', 'at', 'after', 'during', 'that', 'which', 'or'}:
        return -0.13
    return 0.0


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    tail = '' if reset else carry[1]
    match = LAST.search(tail)
    previous = match.group(1).lower() if match else ''
    words = WORDS.findall(tail)
    before = words[-2].lower() if len(words) > 1 else ''
    word, value = token.strip(), 0.0
    if token == ' be':
        value = 0.94 if reset else 1.23
        if previous in {'will', 'shall'} or previous.endswith(("'ll", '’ll')):
            value = 1.75
        elif previous in {'can', 'could', 'cannot', "can't", 'can’t'}:
            value = 1.5
        elif previous in {'may', 'might'}:
            value = 1.05
        elif previous == 'would':
            value = 1.16
        elif previous == 'to' and root(before) in DESIRE - {'need'}:
            value = 1.8
    elif word.lower() == 'be':
        value = 0.65 if word == 'Be' else 0.5
    elif word.lower() == 'been':
        value = 1.27 if previous == 'has' else 1.09
    elif word in {'become', 'became', 'becoming', 'becomes'}:
        value = 0.66 if word == 'becomes' else 0.98
    elif word in {'new', 'New', 'NEW'}:
        value = 1.67
        if word == 'NEW':
            value = 1.2
        elif word == 'new' and not token.startswith(' '):
            value = 1.05
        elif reset:
            value = 2.65
        elif previous in {'a', 'an', 'brand'}:
            value = 2.1 + (0.45 if root(before) in CREATION else 0.0)
        elif tail.strip() and not match:
            value = 1.4
    elif word.lstrip('(.=_-\t') in {'new', 'New'}:
        value = 1.12
    elif word in {'newly', 'newest'}:
        value = 0.7
    elif token in {' a', ' an'}:
        value = 0.76 if reset else article(previous)
    elif word in {'新', '新的', '的新', '成为', '成為'}:
        value = 1.3
    elif word in {'être', 'быть', 'być'}:
        value = 1.05
    elif word in {'ser', 'essere'}:
        value = 0.5
    elif word in {'été', 'sido'}:
        value = 0.8
    elif word == 'being':
        value = 0.11
    return (doc, (tail + token)[-80:]), float(value)

programs.haiku:
"""Layer-0 MLP neuron 1177 (down_proj) as a 'be / new / make-a' detector.

It switches on for the words "be", "been", "become(s/came/ing)" and "new" (and the
equivalents 新, быть, être, 成为), and for "a"/"an" right after a verb: strongly after a
verb of making or creating ("create a", "build a", "make a", "become a"), moderately after
verbs of having or obtaining ("have a", "get a", "receive a"), and slightly negative after
prepositions and "is" ("in a", "by a", "is a").
"""
READS = ()

WORD_LEVEL = {
    " be": 1.3, "be": 0.5, " Be": 0.7, " BE": 0.6, "BE": 0.4, "-be": 0.8,
    " been": 1.2, "been": 1.0, " being": 0.1,
    " become": 1.0, " becomes": 0.7, " became": 0.9, " becoming": 1.0, " Become": 0.8,
    " new": 1.7, " New": 1.7, "New": 1.6, "new": 1.0, "(new": 1.1, "=new": 1.2,
    " NEW": 1.2, " newly": 0.7, "新": 1.3, " 新": 0.8, "新的": 1.4, "成为": 1.5,
    " быть": 1.2, " être": 1.1, " été": 0.8, " нов": 0.6,
}
CREATE_VERBS = {
    "create", "creates", "created", "creating", "make", "makes", "made", "making",
    "build", "builds", "building", "built", "become", "becomes", "became", "becoming",
    "write", "writes", "writing", "add", "adds", "adding", "develop", "develops",
    "developed", "generate", "generates", "start", "starting", "form", "forming",
    "design", "implement", "establish", "need", "needs", "produce",
}
HAVE_VERBS = {"have", "has", "had", "having", "provide", "provides", "providing", "get",
              "take", "find", "want", "got", "obtain", "receive", "buy", "choose"}
# Prepositions and function words: the article after these is not a direct object.
FUNCTION_WORDS = {"in", "on", "at", "by", "from", "of", "as", "than", "that", "or", "and",
                  "is", "was", "are", "with", "into", "over", "under", "through", "like", ","}
ARTICLES = {" a", " an"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if cur in WORD_LEVEL:
        return None, WORD_LEVEL[cur]
    if cur in ARTICLES and len(prefix) > 1:
        prev = prefix.token_strings[-2].strip().lower()
        if prev in CREATE_VERBS:
            return None, 1.4
        if prev in HAVE_VERBS:
            return None, 0.65
        if prev in FUNCTION_WORDS:
            return None, -0.1
        return None, 0.2
    return None, 0.0

programs.luna:
"""Use a few surface-word cues for sparse activation spikes, and a small baseline."""

READS = ()

BE_FORMS = {"be", "been", "become", "becomes", "became"}
LOW_CUES = {"being", "an"}
BASELINE = 0.0054
HIGH = 1.25
LOW = 0.15


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in BE_FORMS or word == "new":
        return None, HIGH
    if word in LOW_CUES:
        return None, LOW
    return None, BASELINE

programs.haiku:
"""Taste, feeling and sensory-quality word detector: layer-0 MLP unit 1178
(layers.0.mlp.down_proj).

At layer 0 the MLP input is close to the current token's own word identity, so this unit
behaves like a word detector. It fires on:
- taste words (sweet, salt, sour, sugar, delicious, 甜, 苦, 辣): the strongest;
- smell words, and pain or other felt-feeling words (pain, suffering, sadness, pleasure);
- temperature words (cold, warm, hot, cool, fresh);
- food and chemical substances (cream, cheese, olive oil, acid, alcohol);
- colour words (red, white, black, dark) and texture words (sticky, slippery, soft, dry);
- plain judgement words (good, free, bad), more weakly.
It is negative on "environment" and weakly negative on abstract or institutional words
(system, united, economy). Everything else predicts 0.

Each word set is a plain concept; each value is the mean activation measured on training
text for that set, in the component's own units.
"""

TASTE = {
    "sweet", "sweets", "sour", "bitter", "salt", "salts", "salty", "sugar", "sugars",
