    'сети': 2.7, 'сет': 1.8, 'mạng': 2.4,
    'ネット': 1.25, 'ワーク': 1.1,
    '网络游戏': 1.4, '网络安全': 1.4, '网络科技': 1.4,
    '网络营销': 2.3, '在网络': 4.6, '在网络上': 2.4,
    '在網路上': 1.5,
}
INFRASTRUCTURE = {
    'framework': 2.0, 'frameworks': 2.2, '框架': 1.3,
    'database': 0.8, 'databases': 0.7,
    'circuit': 0.8, 'circuits': 0.7,
    'platform': 0.7, 'platforms': 0.7, '平台': 0.55,
    'protocol': 0.7, 'protocols': 0.7,
    'infrastructure': 0.65, 'forum': 0.5, 'forums': 0.5,
    '论坛': 0.75, 'socket': 0.25, 'sockets': 0.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, previous_value = carry[1:] if carry and carry[0] == doc else ('', 0.0)
    raw = prefix.token_strings[-1]
    word = raw.strip(' \t\r\n_./-:()\\').lower()
    value = NETWORK_WORDS.get(word, INFRASTRUCTURE.get(word, 0.0))
    if word in {'network', 'networks', 'networking', 'etwork'}:
        value = {'network': 6.7, 'networks': 6.0,
                 'networking': 4.9, 'etwork': 5.8}[word]
        if prev == 'neural':
            value -= 2.4
        elif prev == 'social':
            value -= 1.2
    elif word in {'net', 'nets'}:
        value = 0.5
    elif raw == ' of':
        if prev in {'network', 'etwork'}:
            value = 4.0
        elif prev == 'networks':
            value = 3.0
        else:
            value = 0.5 * previous_value
    elif raw in {'s', 'ed', 'ing'} and previous_value > 0:
        value = previous_value * (0.75 if raw == 's' else 0.5)
    elif raw == 'ей' and prev == 'сет':
        value = 1.9
    return (doc, word, value), float(value)

