programs.sol:
"""Coarse spelling-continuation and lexical approximation.

Unspaced Latin letters continue the preceding token's letter fragment.
Vowel content, capitals, and identifier punctuation set coarse strengths.
Small named sets recognize technical/developer spellings at shared strengths.
The token spellings 'need', 'needs', and 'want' instead use the previous
word's pronoun, auxiliary, or emphasis class. Only adjacent tokens in the
same document are read; most weak, token-specific activity is omitted.
"""
import re

READS: tuple[str, ...] = ()
VOWELS = frozenset('aeiouAEIOU')
# Whole spellings, not tokenizer ids or arbitrary fragment lists.
TECHNICAL_ABBREVIATIONS = frozenset({
    'yaml',
    'jdbc',
    'dsl',
    'lsp',
    'npm',
    'npx',
    'ntp',
    'nlp',
})
DEVELOPER_SPELLINGS = frozenset({
    'bash',
    'jest',
    'jboss',
    'maven',
    'gradle',
    'crates',
})
FIRST_SECOND_PERSON = frozenset(('i', 'we', 'you'))
FUTURE = frozenset(('will', "'ll", '’ll'))
EMPHASIS = frozenset(('also', 'really', 'still', 'already', 'probably'))


def lexical_verb(s, previous):
    word = s.strip().lower()
    p = previous.strip().lower()
    if word not in ('need', 'want', 'needs'):
        return None
    if word == 'needs':
        return 0.03 if p in ('the', 'a', 'no') else 0.14
    if p in FIRST_SECOND_PERSON:
        value = 0.56
    elif p in FUTURE:
        value = 0.66
    elif p in EMPHASIS:
        value = 0.49
    elif p in ('they', 'may', 'would', 'might', "'t", '’t'):
        value = 0.33
    elif p in ('the', 'a', 'no'):
        value = 0.11
    else:
        value = 0.21
    return value if word == 'need' else max(0.02, value - 0.33)


def continuation(s, previous):
    if not (s.isascii() and s.isalpha()):
        return 0.0
    match = re.search(r'[A-Za-z]+$', previous)
    if not match:
        return 0.0
    stem = match.group()
    spelling = (stem + s).lower()
    if spelling in TECHNICAL_ABBREVIATIONS:
        return 1.15 if spelling == 'yaml' else 0.9
    if spelling in DEVELOPER_SPELLINGS:
        return 0.9 if spelling in ('jest', 'jboss') else 0.43
    boundary = len(stem) < len(previous) and previous[-len(stem)-1] in '._/-'
    stem_vowels = any(c in VOWELS for c in stem)
    vowels = sum(c in VOWELS for c in s)
    if not stem_vowels:
        if not vowels:
            if boundary:
                return 0.43 if previous.islower() else 0.24
            if stem.isupper():
                return 0.10 if s.islower() else 0.26
            return 0.0 if s[0].isupper() else 0.17
        if boundary:
            return 0.10 if vowels <= 2 else 0.01
        if s.isupper() and s[0] not in VOWELS:
            return 0.16
        return 0.03
    if len(s) == 1:
        if stem.isupper() and stem[-1] not in VOWELS:
            return 0.14
        if boundary:
            return 0.12
        return 0.02
    if len(stem) == 1 and not previous[0].isspace():
        return 0.06
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    value = lexical_verb(s, previous)
    if value is None:
        value = continuation(s, previous)
    return None, float(value)

