programs.sol:
"""Recognize s-sized pieces of text, with a weaker response to word endings.

The strongest case is the isolated letter s (or S), including mathematical
variables and punctuation-prefixed fragments. Word-final s is weaker, especially
after a long word fragment. Possessive 's fires, but contracted 'is'/'has' is
largely suppressed. Similarly, 'as' fires less in familiar constructions
such as 'such as'.
Selected s-letters in other scripts, s units, HTTP(S), and the US name also fire.
Only the preceding token is remembered, resetting at each document boundary.
"""

import math

READS = ()

# Pronoun/locative contractions and the exceptional imperative "let's".
CONTRACTIONS = {'it', 'he', 'she', 'that', 'there', 'here', 'let', 'this'}
QUESTION_WORDS = {'who', 'what', 'where', 'when', 'why', 'how'}
COMPARISONS = {'same', 'long', 'far', 'soon', 'much', 'many', 'little', 'good'}
ROLE_AS = {
    'serve', 'serves', 'served', 'serving', 'act', 'acts', 'acted', 'acting',
    'regarded', 'considered', 'defined', 'written', 'described', 'represented',
    'identified', 'designated', 'viewed', 'treated', 'classified', 'called',
    'recognized',
}

# Lowercase and uppercase s after punctuation.
PUNCTUATION_S = {
    '(': (2.53, 1.34),
    '/': (2.02, 1.50),
    '-': (1.25, 1.25),
    '.': (1.70, 1.14),
    '_': (1.57, 1.06),
}
S_LETTERS = {
    'с': 0.81,    # Cyrillic es
    'С': 0.63,
    'σ': 1.12,    # Greek sigma
    'ς': 0.77,
    'Σ': 1.10,
    'ſ': 0.30,    # Latin long s
    'س': 0.90,    # Arabic sin
    'الس': 0.89,  # Arabic article followed by sin
    'स': 1.28,    # Devanagari sa
    'ส': 1.40,    # Thai so sua
    'ス': 0.40,   # Japanese su
    '스': 0.40,   # Korean seu
    '斯': 0.48,   # Chinese si, also used in transliteration
}
VOWEL_S = {'es': 0.65, 'Es': 0.93, 'os': 0.38, 'Os': 0.57,
           'us': 0.16, 'Us': 0.44}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    piece = token.strip()
    prev = previous.strip()
    word = prev.strip("'\"‘’“”").lower()
    spaced = token[:1].isspace()
    attached = bool(previous) and previous[-1].isalpha() and not spaced
    value = 0.0

    if piece in {"'s", '’s', "'S", '’S'}:
        value = 1.00
        if word in CONTRACTIONS:
            value = -0.07 if word == 'let' else 0.05
        elif word in QUESTION_WORDS:
            value = 0.27
        elif prev.isdigit():
            value = 1.20
        if piece.startswith('’'):
            value -= 0.07
    elif piece in {'as', 'As', 'AS', '.as', '-as', '_as'}:
        if piece[0] in '.-_':
            value = 0.88
        elif attached:
            value = 0.11 if piece == 'as' else 0.30 if prev.isupper() else 0.85
        elif piece == 'As':
            value = 1.76 if first else 1.18 if spaced else 1.30
        elif piece == 'AS':
            value = 0.64
        else:
            value = 0.77 if spaced else 0.96
            if word in {'such', 'well', 'known'}:
                value = -0.06
            elif word in COMPARISONS:
                value = 0.25
            elif word == 'to':
                value = 0.12
            elif word in ROLE_AS:
                value = 0.51
            elif previous.rstrip().endswith(',') or word in {'and', 'but', 'or'}:
                value = 0.99
    elif piece and piece[-1] in 'sS' and not any(c.isalpha() for c in piece[:-1]):
        capital = piece[-1] == 'S'
        if len(piece) > 1:
            value = PUNCTUATION_S.get(piece[:-1], (1.8, 1.5))[capital]
        elif attached:
            if capital:
                value = 1.50
                if prev.isupper():
                    value = 1.30 if len(prev) == 1 else 0.60 if len(prev) == 2 else 0.13
            else:
                value = max(0.0, 1.45 - 0.64 * math.log(max(1, len(prev))))
                if previous[-1].lower() in 'aeiouy':
                    value += 0.29
                if prev.isupper():
                    value -= 0.10
        elif first:
            value = 1.35 if capital else 2.29
        elif spaced:
            value = 1.64 if capital else 2.25
        else:
            value = 1.69 if capital else 2.67
            if not capital and previous[-1:].isdigit():
                value += 0.15
            elif not capital and previous.endswith('%'):
                value += 0.35
            elif (not capital and len(previous) > 1 and
                  not previous[:1].isspace() and previous[-1] in "'’"):
                # Apostrophe-s split after glued punctuation or an escape.
                value = 1.40
    elif piece in S_LETTERS:
        value = S_LETTERS[piece]
        if piece == 'σ' and attached:
            value = 1.50
        elif attached and piece in {'с', 'س'}:
            value = 0.35 if piece == 'с' else 0.46
    elif piece == 'States' and word == 'united':
        value = 1.10
    elif piece == 'US' and not attached:
        value = 0.47
    elif piece in {'http', 'https'}:
        value = 0.70 if piece == 'https' else 0.25
    elif piece in {'sigma', '\\sigma'}:
        value = 0.85
    elif piece in VOWEL_S:
        value = VOWEL_S[piece]
        if attached:
            value = 0.50 if piece[0].isupper() else 0.02
    elif piece in {'ms', 'ns', 'fs'}:  # Fractions of a second.
        value = 0.10 if attached else 0.65
    elif piece == 'seconds':
        value = 0.54
    elif piece in {'ss', 'SS'}:
        value = 0.49 if piece == 'ss' else 0.29

    return (doc, token), float(value)

