programs.sol:
"""Approximate the start of a written number, with context-dependent strength.

A digit inside a digit run is nearly silent. Starts of numbers in prose are
positive, especially after date words; numeric lists, indentation and symbolic
expressions are weaker. Fullwidth digits respond strongly. The constants are
training averages; this does not attempt to model every word's individual effect.
"""
import re

READS = ()
WORD_GROUPS = (
    ('january february march april may june july august september october '
     'november december jan feb mar apr jun jul aug sep oct nov dec', 0.1),
    ('in on since until during before after born died early late', 0.3),
    ('about around approximately roughly nearly over under than least only', 0.1),
    ('the this that these those', 0.3),
    ('is are be equals equal has have becomes reaches', -0.4),
    ('figure fig table test step equation line level position number case node', -0.4),
    ('return int float double const let var range index count size length '
     'true false null', -0.55),
)
WORD_GROUPS = tuple((set(words.split()), v) for words, v in WORD_GROUPS)
PUNCTUATION_BASE = {
    '.': 0.0, ',': 0.15, ':': 0.45, '/': 0.55, '\\': 0.55,
    '-': 0.4, '_': 0.25, '(': 0.4, '[': 0.1, '{': 0.4,
}


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, previous, tail = carry
    value = 0.0
    if len(token) == 1 and token in '０１２３４５６７８９':
        value = {'０': 0.9, '１': 1.5, '２': 1.85}.get(token, 1.2)
    elif len(token) == 1 and token in '0123456789':
        digit, ch = int(token), previous[-1:]
        offset = {0: 0.3, 1: 0.2, 2: 0.1}.get(digit, 0.0)
        if not previous or ch.isdecimal():
            value = 0.03 if not previous else -0.01
        else:
            base = 0.5
            if ch.isspace() and ch not in '\n\t':
                text = tail.rstrip()
                last = text[-1:]
                if len(tail) - len(text) > 1 or last.isdecimal():
                    base = 0.0
                elif last in '=<>+−^×*([{':
                    base = 0.1
                elif last == '-':
                    base = 0.2
                elif last in ',.:':
                    base = 0.4 if last != ':' else 0.5
                else:
                    base = 0.6
                    words = re.findall(r'\w+', text)
                    word = words[-1].lower() if words else ''
                    for group, adjustment in WORD_GROUPS:
                        if word in group:
                            base += adjustment
                    if len(word) == 1:
                        base -= 0.3
            elif ch in '\n\t':
                base = 0.6
            elif ch in '=<>+−^×*':
                base = 0.15
            elif ch in '$€£¥₹\"\'':
                base = 0.8
            elif '\u3040' <= ch <= '\u30ff' or '\u3400' <= ch <= '\u9fff':
                base = 1.3
            elif ch.isalpha():
                word = previous.strip()
                base = 0.25 if len(word) == 1 else 0.35
                if word.isascii() and len(word) > 1 and word.isupper():
                    base += 0.4
                if previous.startswith('\\x') or word in {'mod', 'sqrt', 'log'}:
                    base -= 0.5
            else:
                base = PUNCTUATION_BASE.get(ch, 0.5)
                if previous.startswith(' ') and ch in '.([{':
                    base += 0.35
                if ch == '-' and previous.startswith(' '):
                    base -= 0.35
                if previous.endswith('__'):
                    base += 0.85
                if ch in '，、；：。':
                    base += 0.7
            value = base + offset
            if ch == '.' and not previous.startswith(' '):
                value = 0.1 if digit in (0, 1, 2) else 0.0
            if ch == '/' and digit == 0:
                value += 0.3
            line = tail.rsplit('\n', 1)[-1]
            value -= 0.25 if '=' in line else 0.0
            value -= 0.1 if any(c in line for c in '{}^∑√×') else 0.0
    return (doc, token, (tail + token)[-150:]), float(value)

programs.haiku:
"""First digit of a number, in running text.

Qwen writes numbers one digit per token. This component responds to the first
digit of a whole number (a digit whose previous token is not a digit). Its size
depends on what comes just before the number:

- after a Chinese or Japanese character: strongest (about 1.3)
- after a space that follows a word, or after a newline, opening bracket, or
  punctuation: strong (the number starts a new phrase or quantity)
- after a math operator, a single variable letter, or a space that follows a
  math operator: weak
- after a decimal point (the digit is a fraction digit, as in 0.05), or after
  a space that follows a digit or indentation: none
- later digits of the same number, and all other tokens: none

It needs no state: it looks back at most three tokens.
"""

READS = ()

MATH = set("=^+-−*<>≠≈×±≤≥")
OPENERS = set("([{\"'")
STRONG, MEDIUM, WEAK = 0.7, 0.5, 0.3
CJK = 1.3


def _is_cjk(token):
    """Chinese ideographs and Japanese kana."""
    return any("\u3040" <= c <= "\u30ff" or "\u3400" <= c <= "\u9fff" for c in token)


def _is_digit(token):
    return len(token) == 1 and token.isdigit()


def _level(prev, before):
    """How strongly a digit after `prev` (itself after `before`) fires."""
    if _is_cjk(prev):
        return CJK
    if "\n" in prev:
        return STRONG
    if prev.strip() == "":
        # a blank token: judge it by the token before it
        if before is None or before.strip() == "" or _is_digit(before.strip()):
            return 0.0
        if before.strip() in MATH:
            return WEAK / 2
        if before.strip().isalpha():
            return STRONG
        return MEDIUM
    word = prev.strip()
    if word == "." and before is not None and _is_digit(before.strip()):
        return 0.0
    if word in MATH:
        return WEAK
    if word.isalpha() and len(word) == 1:
        return WEAK
    if word.isalpha():
        return MEDIUM
    if word in OPENERS or word.endswith(("(", "[", "{")):
        return STRONG
    return MEDIUM


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = prefix.token_strings[-2]
    if not _is_digit(token) or _is_digit(prev):
        return None, 0.0
    before = None
    if len(prefix) >= 3 and prefix.document_ids[-3] == prefix.document_ids[-1]:
        before = prefix.token_strings[-3]
    return None, _level(prev, before)

"""Layer-0 MLP component 1183 (down_proj): a German "oblique case" word detector.

The component goes strongly negative on German words that open a case-marked noun phrase:
  * prepositions that always take the dative: " von" (strongest), " mit", " bei",
    " aus", " nach", " zu", " zwischen", plus the capitalised forms " Bei", " Nach";
  * two-way and accusative prepositions: " für", " auf", " im", " zur", " unter";
  * case-marked articles and endings: " den", " dem", " der", " einem", " eines", "lich";
  * the Romance and Dutch cognates of these: " de", " van", " di", " av".
Every other token (English " of", " to", " in", " for", " the", punctuation, ...) predicts 0.

The value is a fixed strength per word, its typical activation in the training text, so the
prediction does not depend on the context.
"""

READS = ()

DATIVE_PREPOSITIONS = {
    " von": -7.1, " mit": -5.2, " bei": -3.5, " aus": -2.7, " nach": -2.7, " zu": -2.5,
    " zwischen": -3.3, " Bei": -3.1, " Nach": -2.4,
}
OTHER_PREPOSITIONS = {" für": -1.3, " auf": -1.3, " im": -0.8, " zur": -1.2, " Unter": -1.6}
ARTICLES = {" den": -2.2, " dem": -0.6, " der": -0.4, " einem": -0.9, " eines": -1.4, " Den": -0.8}
COGNATES = {" de": -0.7, " van": -1.9, " di": -0.6, " av": -0.5, "lich": -1.6}

VALUE = {**DATIVE_PREPOSITIONS, **OTHER_PREPOSITIONS, **ARTICLES, **COGNATES}


def step(carry, prefix, upstream):
    return carry, VALUE.get(prefix.token_strings[-1], 0.0)

programs.luna:
"""Mark comparison and relative/absolute wording, with ``to`` after ``relative``.

The strongest response is to ``relative`` itself. A few related comparison
forms and the phrase ``relative to`` receive smaller responses.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    previous = carry[0] if carry and carry[1] == doc else ""

    if word == "relative":
        value = -4.55
    elif word == "absolute":
        value = -1.15
    elif word in {"compared", "relatively", "环比"}:
        value = -0.66
    elif word == "相对":
        value = -1.62
    elif word == "to" and previous == "relative":
        value = -2.20
    else:
        value = 0.0

    return (word, doc), value

programs.sol:
"""Recognize the word family 'public', with weaker free-availability signals.

This is primarily lexical, not a test of whether something really is public:
'public' in prose and in code both trigger it. The Chinese/Japanese public
morpheme 公 also fires, especially alone or in words for open/public access.
Smaller signals cover publication, republic, community, and free/no-charge
vocabulary. An immediately preceding @Override annotation lowers the signal.
A space-prefixed public is slightly stronger when preceded by a letter.
A short text tail is carried forward and reset at document boundaries.
Amplitudes approximate training measurements; longer compounds dilute 公.
"""
READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    next_carry = (doc, (tail + raw)[-100:])
    # A byte-fragment token can finish 公 even though decoded alone it is �.
    if '\ufffd' in raw and prefix.text_prefixes[-1].endswith('公'):
        return next_carry, 10.5
    text = raw.strip().lstrip('/-_')
    word = text.lower()
    value = 0.0
    if word == 'public':
        if text.isupper():
            value = 6.6
        elif text[0].isupper():
            value = 7.7
        elif raw.startswith('\t'):
            value = 6.9
        elif raw.startswith('/'):
            value = 6.7
        else:
            value = 7.1 if raw.startswith(' ') else 7.85
        if tail.rstrip().endswith('@Override'):
            value -= 1.3
        elif raw == ' public' and tail and tail[-1].isalpha():
            value += 0.4
    elif word == 'publicly':
        value = 5.35
    elif word == 'publicity':
        value = 3.7
    elif word in {'publication', 'publications'}:
        value = 2.3 if text.islower() else 3.1
    # Romance-language stems and forms of 'public'.
    elif word in {'publi', 'pubb', 'úblico', 'ública', 'público', 'pública'}:
        value = 2.8
    elif word == 'ublic':  # the public stem split after its initial p
        value = 4.15
    elif word in {'pub', 'publish', 'published', 'publishing', 'publishes'}:
        value = 1.4
    elif word in {'publisher', 'publishers', 'unpublished'}:
        value = 0.85
    elif word == 'republic':
        value = 1.95
    elif word in {'republican', 'republicans'}:
        value = 0.8
    elif '公' in text:
        if text == '公':
            value = 8.2
        elif text in {'公开', '公開', '公众', '公眾'}:  # open / the public
            value = 5.7
        elif text in {'公共', '公立'}:  # public / state-run
            value = 4.0
        elif text.startswith('公司'):  # company
            value = 1.05
        else:
            value = 5.8 / len(text) ** 1.5
    elif text in {'공', 'công', 'Công'}:  # Korean / Vietnamese public morpheme
        value = 2.4
    elif word == 'free' or text == '免费':
        value = 1.05
    elif word == 'gratis' or text in {'無料', '免費'}:
        value = 0.7
    elif word in {'community', 'communities', 'official', 'officially',
                  'popular', 'popularity', 'unpopular'}:
        value = 0.65
    elif word == 'export':
        value = 0.9
    return next_carry, value

programs.luna:
"""Approximate a public/free-access cue using the current token alone.

“Public” is the strongest cue; “free” and selected related words get
smaller responses, while other words predict zero.
"""

READS = ()

PUBLIC = {"public", "公"}
PUBLIC_PEOPLE = {"公众"}
FREE = {"free", "免费", "免費", "無料", "gratis"}
RELATED = {
    "community": 0.65,
    "popular": 0.65,
    "unpopular": 0.65,
    "official": 0.65,
    "company": 0.65,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in PUBLIC:
        return None, 7.2
    if word in PUBLIC_PEOPLE:
        return None, 5.0
    if word.startswith("public"):
        return None, 2.0
    if word in FREE:
        return None, 1.15
    if word in RELATED:
        return None, RELATED[word]
    if word == "export":
        return None, 0.9
    return None, 0.0

programs.haiku:
"""Layer-0 MLP down-projection component 1187, read as a small token-text detector.

It looks only at the current token's text and returns a small signed value:
- A Persian-only letter (ی ک گ چ پ ژ) inside a word, i.e. not word-initial: strongly negative
  (about -0.6; the Persian yeh 'ی' and the chi 'چ' are the most negative).
- A Dutch-only function word with a leading space (het, een, van, met, die, dit, voor, te,
  dat): negative (about -0.4).
- Any other Arabic-script piece inside a word: slightly negative (about -0.05).
- An Arabic-script token that starts a word (leading space): positive (about +0.15).
- Everything else: 0.

The sizes are least-squares fits to activations on training rows. Most of the component's
variance is a long tail of token-specific values with no shared concept, so this program
explains only a few percent of it.
"""

READS = ()

PERSIAN_LETTERS = set("یکگچپژ")
DUTCH_WORDS = {" het", " een", " van", " met", " die", " dit", " voor", " te", " Die", " dat"}


def is_arabic_script(text):
    return any(
        "؀" <= ch <= "ۿ" or "ݐ" <= ch <= "ݿ" or "ﭐ" <= ch <= "﻿"
        for ch in text
    )


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if is_arabic_script(text):
        if text[:1] == " ":
            value = 0.15
        elif any(ch in PERSIAN_LETTERS for ch in text):
            value = -0.6
        else:
            value = -0.05
    elif text in DUTCH_WORDS:
        value = -0.4
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Local clause openings: strongest after knowing, checking, or deciding.

Question words after information-seeking words get a large positive estimate;
' that' is weaker. Prepositions and nearby recipient phrases also increase the
estimate. Boundaries suppress it; inflection, case, and token spacing modify
it. Literal display continuations and a few other non-clausal continuations
get negative estimates. A few non-English openers get constant estimates;
other tokens usually get zero. This is a lexical approximation using two
preceding tokens, not a parser. Document boundaries reset its state.
"""
READS = ()

# Semantic verb classes and their question-opening strengths.
VERBS = (
    (7.3, 'know'),
    (8.3, 'determine decide'),
    (6.6, 'check verify ascertain see understand comprehend discern'),
    (6.1, 'tell indicate specify clarify reveal notify inform remind'),
    (5.9, 'ask wonder inquire'),
    (5.2, 'show explain teach demonstrate describe illustrate learn find '
     'discover remember recall recollect identify select consider investigate '
     'examine explore analyze assess evaluate calculate predict choose guess '
     'discuss test detect estimate define interpret track pinpoint'),
    (4.6, 'realize recognize notice perceive doubt'),
    (3.0, 'say state mention note report announce claim argue think believe '
     'suppose assume hope expect imagine'),
    (4.0, 'ensure confirm prove establish suggest imply require agree '
     'guarantee assure observe conclude'),
)
LEXICON = {}
for strength, words in VERBS:
    for word in words.split():
        LEXICON[word] = strength
        third = (word[:-1] + 'ies' if word.endswith('y') else
                 word + ('es' if word.endswith(('s', 'ch', 'sh')) else 's'))
        past = (word[:-1] + 'ied' if word.endswith('y') else
                word + ('d' if word.endswith('e') else 'ed'))
        ongoing = (word[:-1] if word.endswith('e') and not
                   word.endswith('ee') else word) + 'ing'
        for form, penalty in [(third, 0.9), (past, 1.7), (ongoing, 0.4)]:
            LEXICON[form] = strength - penalty
for forms, root in (
    ('knew known', 'know'), ('saw seen', 'see'), ('told', 'tell'),
    ('shown showed', 'show'), ('taught', 'teach'), ('found', 'find'),
    ('understood', 'understand'), ('thought', 'think'), ('said', 'say')
):
    for word in forms.split():
        LEXICON[word] = LEXICON[root] - 1.7
for word in 'sure unsure certain uncertain clear unclear unknown aware'.split():
    LEXICON[word] = 6.4

# Base response and sensitivity to the preceding phrase.
QUESTIONS = {
    'what': (0.2, 1.15),
    'how': (0.6, 0.91),
    'why': (0.36, 0.81),
    'where': (0.07, 0.92),
    'when': (-0.12, 0.78),
    'which': (-0.03, 1.16),
    'who': (0.02, 0.95),
    'whom': (-0.24, 0.65),
    'whose': (0.3, 0.45),
    'if': (-0.18, 0.99),
    'whether': (2.05, 0.70),
}
TOPIC = {'on', 'upon', 'about', 'over'}
RECIPIENTS = {'you', 'me', 'us', 'him', 'her', 'them', 'readers', 'students'}
DISPLAY_DETAILS = {
    'page': -4.5,
    'pages': -2.8,
    'full': -2.5,
    'tags': -2.1,
}
OTHER_OPENERS = {
    '是否': 1.6,
    '哪些': 1.2,
    '何时': 1.2,
    ' que': 0.28,
    ' qué': 1.6,
}


def response(token, previous, before):
    word, prev, prior = (s.strip().lower() for s in (token, previous, before))
    if word not in QUESTIONS and word != 'that':
        if prev in {'show', 'shows', 'showing'} and word in DISPLAY_DETAILS:
            return float(DISPLAY_DETAILS[word])
        if word in {'more', 'less', 'better', 'worse'} and prev in LEXICON:
            return -1.5 if prev.startswith('know') else -0.8
        if word in {'me', 'us'} and prev in {'tell', 'tells', 'show', 'shows'}:
            return -1.0
        return float(OTHER_OPENERS.get(token, 0.0))
    if (not prev or not any(c.isalpha() for c in prev) or
        previous.rstrip().endswith(',') or prev in {'and', 'or', 'but', 'so'}):
        return 0.9 if word == 'whether' else 0.0
    strength = LEXICON.get(prev, 0.7)
    if not previous.startswith(' ') and prev not in LEXICON:
        for n in range(1, min(len(before), 12) + 1):
            joined = (before[-n:] + previous).lower()
            if joined in LEXICON:
                strength = LEXICON[joined]
                break
    if prev == 'out':
        strength = 7.3 if prior in {'find', 'found', 'figure'} else 4.7
    elif prev in RECIPIENTS and prior in LEXICON:
        strength = 5.3
    elif prev in {'exactly', 'precisely', 'just', 'here', 'now'}:
        strength = LEXICON.get(prior, 1.5)
    elif prev in TOPIC:
        strength = LEXICON.get(prior, 3.1)
    elif prev in {'of', 'to', 'at'}:
        strength = 1.5
    elif prev in {'question', 'idea', 'clue', 'knowledge', 'uncertainty'}:
        strength = 4.3
    elif prev in {'matter', 'matters'}:
        strength = 3.8
    elif prev in {'is', 'are', 'was', 'were', 'be'}:
        strength = 0.25
    if word == 'that':
        return 0.2 * strength if token == ' that' else 0.0
    base, scale = QUESTIONS[word]
    value = base + scale * strength
    if token.strip() != word or not token.startswith(' '):
        value = 0.7 * value if strength > 4.5 else 0.0
    return float(value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = (('', '') if carry is None or carry[0] != doc
                        else carry[1:])
    token = prefix.token_strings[-1]
    return (doc, token, previous), response(token, previous, before)

programs.haiku:
"""Embedded questions and clauses.

Fires on a question word (what, how, which, whether, if, why, where, who, when) or on
"that" when it opens an indirect question or a clause inside a sentence, as in
"I don't know WHAT...", "to determine WHETHER...", "let me check IF...",
"tell you HOW...", "we show THAT...".

Its size depends on the verb that governs the word (the word just before it, or the verb
before an object pronoun such as "tell you"):
  - a verb of finding out, asking or checking (know, determine, check, see, explain,
    tell, investigate, ask, wonder, consider, ...): strong (about 6), strongest for
    what, how and whether;
  - a preposition ("on", "about", "of") : about 2;
  - a verb of saying or thinking (say, found, suggest, ...): about 1;
  - sentence start, punctuation or a conjunction ("So how", "and what", ", what"): zero.
A "that" counts only after a verb (about 1); as a determiner or relative it is zero.
"when" and "who" are weaker, since they are often temporal or relative."""

READS = ()

QUESTION_WORDS = {
    "what", "how", "which", "whether", "if", "why", "where", "who", "whom", "whose", "when",
}
FINDING_OUT = {
    "know", "knew", "known", "knowing", "knows", "determine", "determining", "determined",
    "determines", "check", "checking", "checked", "checks", "see", "seeing", "seen", "sees",
    "explain", "explaining", "ask", "asks", "asked", "asking", "tell", "telling", "told",
    "tells", "learn", "learned", "learning", "understand", "understanding", "understood",
    "calculate", "calculating", "sure", "out", "describing", "demonstrate", "demonstrates",
    "test", "testing", "figure", "wonder", "wondered", "wondering", "decide", "decided",
    "deciding", "investigate", "investigated", "investigating", "discover", "identify",
    "identified", "estimate", "measure", "verify", "consider", "considering", "considered",
    "unclear", "define", "defined", "examine", "examined", "analyze", "analyzed", "guess",
    "discuss", "discussed", "predict", "compute", "evaluate", "study", "show", "shows",
    "showed", "shown", "illustrate", "illustrates", "question", "unsure", "clear",
}
WEAK_VERBS = {
    "say", "said", "saying", "says", "found", "find", "suggest", "suggests", "suggested",
    "indicate", "indicates", "indicated", "think", "thinks", "believe", "believes",
    "assume", "ensure", "ensures", "confirm", "confirms", "note", "noted", "state",
    "states", "stated", "reveal", "revealed", "means", "mean", "claim", "claims", "hope",
    "hoping", "argue",
}
OBJECT_PRONOUNS = {"you", "me", "us", "them", "him", "her"}
PREPOSITIONS = {"on", "about", "of", "at", "for", "to", "in", "with"}
NO_CONTEXT = {
    "", ".", ",", "?", "!", ";", ":", ")", "(", "\"", "'", "-", "\n",
    "and", "but", "so", "or", "as", "even", "then", "because",
}
# how strongly each word opens an indirect question, relative to "what" and "how"
WORD_SCALE = {
    "what": 1.0, "how": 1.0, "whether": 1.0, "why": 0.8, "where": 0.8, "if": 0.8,
    "which": 0.8, "who": 0.5, "whom": 0.4, "whose": 0.4, "when": 0.4,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in QUESTION_WORDS and word != "that":
        return carry, 0.0
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower()
    if before in NO_CONTEXT:
        return carry, 0.0
    if before in OBJECT_PRONOUNS and len(prefix.token_ids) >= 3:
        before = prefix.token_strings[-3].strip().lower()
    if word == "that":
        if before in FINDING_OUT or before in WEAK_VERBS:
            return carry, 1.2
        return carry, 0.0
    if before in FINDING_OUT:
        value = 6.0
    elif before in PREPOSITIONS:
        value = 2.0
    elif before in WEAK_VERBS:
        value = 1.0
    elif word in {"what", "how", "whether", "why", "where"}:
        value = 2.0
    else:
        value = 0.5
    return carry, value * WORD_SCALE.get(word, 1.0)

programs.sol:
"""Spelled quantities, particularly numbers in the teens.

The largest estimates go to eleven through nineteen and Chinese 十-plus-unit
spellings. Smaller numbers, numeral suffixes, Roman numerals, calendar months,
and adolescence words give weaker cues. Decimal digit strings and
unlisted words give zero. Strengths are fitted responses, not numeric values.
"""
import re

READS = ()
NUMBERS = {
    'one': 0.03, 'two': -0.15, 'three': 0.52, 'four': 0.74,
    'five': 0.98, 'six': 1.3, 'seven': 1.54, 'eight': 1.67,
    'nine': 1.92, 'ten': 2.85, 'eleven': 5.63, 'twelve': 5.93,
    'twenty': 4.15, 'thirty': 3.2, 'forty': 3.4, 'fifty': 2.45,
    'sixty': 2.8, 'seventy': 2.8, 'eighty': 2.75, 'ninety': 2.8,
    'hundred': 1.1, 'thousand': 0.24,
}
TEENS = 'thirteen fourteen fifteen sixteen seventeen eighteen nineteen'.split()
NUMBERS.update(dict.fromkeys(TEENS, 6.7))
CUES = {
    # Ordinal number words.
    'second': -0.13, 'third': -0.08, 'fourth': 0.18, 'fifth': 0.35,
    'sixth': 0.67, 'seventh': 1.05, 'eighth': 1.32, 'ninth': 1.5,
    'tenth': 2.6, 'eleventh': 4.6, 'twelfth': 4.95, 'twentieth': 4.7,
    # Calendar months.
    'january': 0.68, 'february': 0.32, 'august': 0.19,
    'september': 0.38, 'october': 0.93, 'november': 1.26,
    'december': 1.84, 'dec': 0.42,
    # Ages, counted groups, and time units.
    'teen': 2.37, 'teens': 2.2, 'teenage': 3.05, 'teenager': 2.82,
    'teenagers': 2.3, 'adolescent': 2.0, 'adolescents': 1.4,
    'adolescence': 1.85, 'dozen': 1.33, 'dozens': 1.08,
    'decade': 1.6, 'decades': 1.05, 'midnight': 1.4, 'noon': 1.1,
    'christmas': 1.0, '青少年': 1.16,
}
ROMANS = {
    'II': 0.4, 'III': 0.35, 'VI': 0.4, 'VII': 1.0, 'VIII': 1.2,
    'IX': 0.4, 'XI': 1.0, 'XII': 2.55, 'XIII': 3.3, 'XIV': 3.54,
    'XV': 2.3, 'XVI': 3.1, 'XVII': 3.0, 'XVIII': 3.0,
    'XIX': 3.0, 'XX': 0.6,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower()
    match = re.search(r'[A-Za-z]+$', tail + token)
    tail = match.group()[-30:] if match else ''
    whole = tail.lower()
    value = NUMBERS.get(word, CUES.get(word, 0.0))
    # Numeric word endings can be separate tokens.
    if token == 'teen':
        value = 6.7 if whole in NUMBERS else 4.3
