    '気': 1.37, '氣': 0.74, '气': 0.69, '機': 0.88,
    '机': 0.65, '期': 0.78, '記': 0.81, '记': 0.62,
    '金': 0.8, '契': 1.22, '崎': 0.62, '激': 0.78,
