    'キ': 4.95, 'き': 2.92, 'ギ': 2.97, 'ぎ': 1.12,
    'チ': 0.95, 'ち': 0.41, 'し': 0.61, 'ヒ': 1.17,
    'ジ': 0.73, 'コ': 0.62, 'キー': 1.44, 'スキ': 1.85,
}


