    elif title:
        scale = 0.55 ** (title - 1) if title <= 3 else 0.0
        if position == 1:
            if word == 'what':
                value = -3.1 * scale
            elif word in QUESTION_WORDS:
                value = -2.4 * scale
            elif word in QUESTION_AUXILIARIES or not token.strip():
                value = -1.8 * scale
            elif word.isalpha():
                value = -1.0 * scale
        elif '\n' in token:
            value = -2.5 * 0.85 ** position * scale
        if '\n' in token:
            title = 0
    return (doc, position, token, code, title), float(value)

"""A lexical detector for kinds, types, classes, and examples ('such').

It also responds on 'of' after a noun that introduces a kind or collection.
Chinese class/kind words are especially strong. Code punctuation, plurals,
and class declarations alter the strength; other tokens are left quiet.
"""
READS = ()

# Nouns in the construction '<classification or collection> of ...'.
OF_GROUPS = (
    (2.4, {'type', 'kind', 'kinds'}),
    (2.8, {'types'}),
    (2.0, {'sort', 'sorts'}),
    (1.5, {'class', 'classes', 'category', 'categories'}),
    (1.1, {'species', 'classification'}),
    (0.95, {'variety', 'varieties', 'forms'}),
    (0.75, {'form', 'piece', 'pieces', 'family', 'examples'}),
    (0.65, {'instance', 'instances', 'genus'}),
    (0.5, {'group', 'groups', 'version', 'versions', 'pair', 'pairs',
           'subset', 'subsets', 'branch', 'branches', 'style'}),
    (0.4, {'set', 'sets', 'range', 'example', 'series', 'collection'}),
)
OF = {word: value for value, words in OF_GROUPS for word in words}
DECLARATION = {'public', 'private', 'protected', 'abstract', 'static',
               'final', 'partial', 'export'}
TRADITIONAL = str.maketrans('類種這別', '类种这别')

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    clean = token.strip()
    word = clean.lstrip('_-./\\(').lower()
    spaced = bool(token and token[0].isspace())
    value = 0.0
    if word == 'such':
        value = 1.14 if clean[:1].isupper() else 1.0
    elif word in {'type', 'types'}:
        value = (1.7 if spaced else 1.25) if word == 'types' else (
            1.17 if spaced else 0.87)
        if clean.startswith(('_', '-')):
            value = 1.3 if word == 'types' else 0.78
        elif clean.startswith('.'):
            value = 1.4 if clean[1:2].isupper() else 1.05
    elif word in {'class', 'classes'}:
        value = (1.3 if spaced else 1.18) if word == 'classes' else (
            0.75 if spaced else 0.6)
        if clean[:1].isupper():
            value += 0.3
        if clean.startswith(('.', '_')):
            value = 1.35
        if word == 'class' and previous in DECLARATION:
            value = 0.22
    elif word in {'category', 'categories', 'categor'}:
        value = 2.0 if spaced else 1.8
    elif word in {'classification', 'classify', 'classified', 'subclass'}:
        value = 1.1
    elif word in {'kind', 'kinds', 'kinda'}:
        value = 1.3 if word == 'kinds' else (0.85 if spaced else 0.6)
    elif word in {'genre', 'genres', 'tipo', 'tipos'}:
        value = 1.0
    elif word in {'clazz', 'classe', 'clases', 'класс', 'тип', 'типа',
                  'クラス', 'タイプ', 'نوع'}:
        value = 0.7
    elif word == 'of':
        value = OF.get(previous, 0.0)
    else:
        c = clean.translate(TRADITIONAL)
        if c == '类':
            value = 5.9
            if previous in {'种', '種', '分'}:
                value = 4.5
        elif c in {'人类', '种类', '分类', '类别', '之类'}:
            value = 3.0
        elif c in {'类型', '类型的', '之类的', '类似'}:
            value = 2.0
        elif c in {'类似于', '类似的'}:
            value = 1.1
        elif c.endswith('类') and len(c) <= 3:
            value = 5.0
        elif c.endswith('种') and len(c) <= 4:
            value = 0.85
    return (doc, word), float(value)

programs.luna:
"""Mark words that name or introduce a type, class, or category.

The rule catches 'such', category words, and 'of' after a short list of
category cues; code-style type and class names are included as well.
"""
READS = ()

TYPE_WORDS = {
    "type", "types", "class", "classes", "clazz", "category",
    "categories", "kind", "kinds", "genre",
}
CODE_SUFFIXES = ("_type", "-type", "_class", "-class")
OF_CUES = {
    "form", "instance", "class", "kind", "type",
    "category", "genre", "sort", "variety",
}
OTHER_CLASS_WORDS = {"類", "クラス"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()

    if word == "such":
        return None, 1.05
    if word in TYPE_WORDS:
        return None, 1.0
    if word.endswith(CODE_SUFFIXES):
        return None, 0.8

    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().casefold()
    if word == "of" and previous in OF_CUES:
        return None, 0.8
    if word in OTHER_CLASS_WORDS:
        return None, 0.9
    return None, 0.0

programs.sol:
"""A spelling-based approximation, not a general semantic or pronunciation model.

Strong positive responses mark document-end separators and tab-plus-space
indentation. Smaller responses mark short u-vowel pieces (especially ua),
including consonant+ua, suit/sue/suo, and some Cyrillic and Arabic spellings.
The word dual has a separate strong response. Other spelling responses fade
with piece length. A vowel can also continue a u from
the preceding token, within the same document. Unrecognized tokens get zero.
"""
import math

READS = ()
CONSONANTS = frozenset('bcdfghjklmnpqrstvwxyz')


def fade(strength, decay, extra):
    return strength * math.exp(-decay * max(extra, 0))


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if text == '<|endoftext|>':
        value = 1.67
    elif text.startswith('\t') and text.isspace() and ' ' in text:
        spaces = text.count(' ')
        value = 0.8 if spaces < 4 else 1.0 if spaces < 17 else 0.7
        if spaces % 4 == 0:
            value -= 0.28
        if '\n' in text or '\r' in text:
            value -= 0.3
    elif word == 'dual':
        value = 2.6
    elif word.startswith('ua'):
        value = fade(3.0, 0.42, len(word)-2)
        if text[0].isspace():
            value *= 0.3
    elif word.startswith(('ue', 'ui', 'uo')):
        strength = 1.1 if word.startswith('uo') else 0.6
        decay = 0.35 if word.startswith(('ui', 'uo')) else 0.2
        value = fade(strength, decay, len(word)-3)
        if text[0].isspace():
            value *= 0.7
    elif len(word) >= 3 and word[0] in CONSONANTS and word[1:3] == 'ua':
        value = fade(1.8, 0.55, len(word)-3)
        if word.startswith('qua') and word.endswith(('nt', 'rt')):
            value = 1.1
    elif word.startswith(('suit', 'sue', 'suo', 'tuo', 'seu')):
        value = fade(1.2, 0.35, len(word)-3)
    elif text and text[0].isalpha() and word.startswith(('уй', 'уют')):
        value = fade(1.5, 0.8, len(word)-2)
    elif text and text[0].isalpha() and word.startswith(('ва', 'во')):
        value = fade(0.5, 1.0, len(word)-3)
    elif text and text[0].isalpha() and word.startswith('وا'):
        value = fade(1.15, 0.5, len(word)-3)
    elif text and text[0].isalpha() and word.startswith(('oa', 'iao')):
        value = fade(0.8, 0.2, len(word)-2)
    elif previous.lower().endswith('u') and text and text[0] in 'aeio':
        value = fade(1.0, 0.3, len(word)-1)
    return (doc, text), float(value)

programs.luna:
"""A small lexical cue catches sparse positive responses at document ends and in code."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<|endoftext|>":
        return None, 0.825
    if "\t" in token:
        return None, 0.45
    return None, 0.0

programs.sol:
"""Eight is the main feature: digit 8, eight/eighth/eighty/eighteen,
Chinese 八 and numeric compounds, Roman VIII, fullwidth ８, and August.

The digit's strength varies with its immediate numeric or punctuation
context and decreases gently with document position. Nine has a weaker
context-sensitive response, strongest after another nine. Smaller positive
responses mark end-of-text, triple-hash headings, and some indentation.
Other lexical variation is left at zero. State resets between documents.
"""
import math

READS = ()

# Adjustments to digit 8 according to the immediately preceding digit.
EIGHT_AFTER_DIGIT = {
    '0': -0.31,
    '1': -0.03,
    '2': -0.23,
    '3': 0.40,
    '4': -0.10,
    '5': 0.12,
    '6': -0.19,
    '7': 0.12,
    '8': -0.32,
    '9': 0.49,
}
EIGHT_AFTER_SEPARATOR = {
    ' ': 0.15,
    '.': -0.41,
    '-': 0.35,
    ',': -0.25,
    '=': -0.33,
}
NINE_AFTER_DIGIT = {
    '3': 0.36,
    '4': 0.12,
    '5': 0.21,
    '7': 0.21,
    '8': 0.03,
    '9': 0.66,
}
NUMBER_WORDS = {
    'eight': 2.12,
    'eighth': 2.35,
    'eighty': 2.01,
    'eighteen': 1.39,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    previous = carry[1] if same_document else ''
    position = carry[2] + 1 if same_document else 0
    word = token.strip().lstrip('-')
    lower = word.lower()
    value = 0.0

    if token == '8':
        value = 2.54 - 0.046 * math.log1p(position)
        value += EIGHT_AFTER_DIGIT.get(previous, 0.0)
        value += EIGHT_AFTER_SEPARATOR.get(previous, 0.0)
        if previous not in EIGHT_AFTER_SEPARATOR:
            if previous.startswith(' ') and not previous[-1:].isalnum():
                value -= 0.22
            elif previous[-1:].isalpha():
                value += 0.45
    elif token == '9':
        value = NINE_AFTER_DIGIT.get(previous, -0.07)
    elif word == '八':
        value = 3.68
    elif word == '第八':
        value = 3.13
    elif '八' in word and all(c in '零〇一二三四五六七八九十百千万' for c in word):
        value = 2.8
    elif word in ('８', 'Ⅷ', 'VIII'):
        value = 1.61 if word == 'VIII' else 2.20
    elif lower in NUMBER_WORDS:
        value = NUMBER_WORDS[lower]
        if word == 'Eight' and token.startswith(' '):
            value = 2.74
        elif word == 'Eighth':
            value = 2.06
    elif lower in ('august', 'aug', 'aug.', 'août', 'agosto', 'август'):
        if lower == 'august':
            value = 1.72 if token.startswith(' ') else 1.50
        elif lower in ('aug', 'aug.'):
            value = 1.43 if token.startswith(' ') else 0.94
        else:
            value = 1.14
    elif token == '<|endoftext|>':
        value = 1.46
    elif token.strip() == '###':
        value = 0.85
    elif token == ' ' and previous.endswith('\n'):
        value = 0.51
    elif token.startswith('\t') and token[1:] == ' ' * (len(token) - 1):
        if len(token) >= 10:
            value = 0.42
    elif token == ' ' * len(token) and 12 <= len(token) <= 22:
        value = 0.19
    return (doc, token, position), value

programs.haiku:
"""Chat-template closing tags: a tool call ends with a strong negative value,
a reasoning block with a positive one. Everything else is predicted as zero."""

READS = ()

# Typical activation on each closing tag (measured on training text).
CLOSING_TAGS = {
    "</tool_call>": -0.285,
    "</think>": 0.148,
    "</tool_response>": 0.024,
    "<|im_end|>": -0.040,
}

def step(carry, prefix, upstream):
    return None, CLOSING_TAGS.get(prefix.token_strings[-1], 0.0)

programs.sol:
"""Literal backslash escapes, dominated by written newlines and tabs.

Completing an escape in a separate token is stronger than a whole escape
in one token; repeated backslashes weaken it. Common TeX command beginnings
are distinguished from newline/tab completions. Other escape letters,
TeX/documentation formatting commands, and printf fields respond weakly.
Actual whitespace and ordinary text usually give zero. Only the previous
token is retained, and it is forgotten at a document boundary.
"""
READS = ()

TEX_N = set('new non not notin nu neg neq nabla no normal nolimits'.split())
TEX_T = set('text times theta tau til tilde to time tiny top tag '
            'tfrac triangle'.split())
FORMATTING = set('text small big quad item bib section bf it sc em rm '
                 'param brief'.split())
WHOLE_ESCAPES = {'\\n': 4.85, '\\t': 4.02, '\\r': 1.10}
SPLIT_ESCAPES = {'n': 8.25, 't': 5.55, 'r': 3.0, '0': 2.0}
HEX_DIGITS = set('0123456789abcdefABCDEF')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token in WHOLE_ESCAPES:
        value = WHOLE_ESCAPES[token]
    elif token == '\\':
        value = 0.30
    elif token.startswith(('\\x', '\\u')):
        value = 0.70
    elif previous.endswith('\\') and token:
        slashes = len(previous) - len(previous.rstrip('\\'))
        if token in SPLIT_ESCAPES:
            value = SPLIT_ESCAPES[token]
            if token in {'n', 't'}:
                value /= slashes ** 0.55
        elif token.startswith('n') and token not in TEX_N:
            value = 4.15 / slashes ** 0.30
        elif token.startswith('t') and token not in TEX_T:
            value = 2.50
        elif token.startswith('x') and set(token[1:]) <= HEX_DIGITS:
            value = 2.80
        elif len(token) == 1 and token.isalpha():
            value = 1.50
        elif token in FORMATTING:
            value = 0.85
        elif token in {'non', 'not', 'neg'}:
            value = 1.50
        elif token in {'nu', 'to'}:
            value = 0.85
        elif token[0].isalpha():
            value = 0.05
    elif previous.endswith('%'):
        if token == 's':
            value = 1.2
        elif token == 'd':
            value = 0.5
    return (doc, token), float(value)

programs.luna:
"""Recognize visible backslash escapes in the current text.

The strongest response is to the escape for a line break (backslash plus n).
Tab escapes and a few combined-token spellings get smaller positive values.
"""
READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ""
    token = prefix.token_strings[-1]
    slashes = len(previous) - len(previous.rstrip("\\"))

    if token == "n" and slashes == 1:
        value = 8.23
    elif token == "n" and slashes >= 2:
        value = 6.12
    elif token.startswith("n") and slashes == 1:
        value = 4.78
    elif token == "t" and slashes == 1:
        value = 5.99
    elif token == "\\n":
        value = 4.79
    elif token == "\\t":
        value = 4.11
    elif token.startswith("x") and slashes == 1:
        value = 2.8
    else:
        value = 0.0

    return (document, token), float(value)

programs.sol:
"""A sparse lexical signal for event progression versus release/placement.

Positive: 'soon', rapid/easy/successful-action adverbs, and Chinese words
meaning then, shortly, or finally. Negative: 放 (release/put), related
vocabulary, Korean 방, and opening-tag boundaries. A smaller separate signal
recognizes Git's .git path fragment. Unlisted tokens predict zero. The idiom
'as soon' is weaker than standalone 'soon'. This is lexical, not an event parser.
"""
READS = ()

ADVERBS = (
    (1.7, {'shortly'}),
    (1.3, {'quickly', 'easily', 'suddenly', 'swiftly', 'promptly'}),
    (1.55, {'seamlessly'}),
    (0.9, {'eventually', 'readily'}),
    (0.75, {'subsequently', 'successfully', 'neatly'}),
    (0.55, {'immediately', 'instantly', 'rapidly', 'smoothly', 'steadily', 'duly'}),
    (0.35, {'slowly', 'gradually', 'efficiently', 'effectively',
            'consequently', 'accordingly', 'thereby'}),
    (0.22, {'finally', 'ultimately'}),
)

# Chinese temporal/result connectives, including traditional spellings.
TRANSITIONS = (
    (4.35, {'遂', '于是', '於是'}),
    (1.75, {'便', '便可', '从此', '随即'}),
    (2.2, {'很快', '很快就', '不久'}),
    (1.2, {'终于', '尽快', '顺利', '顿时', '随后', '由此', '竟', '渐渐'}),
    (1.0, {'迅速', '就会', '立刻', '忽然', '竟然', '这时'}),
    (0.75, {'从而', '就可以', '即可', '就能', '居然', '接著', '后来'}),
    (0.5, {'突然', '好像'}),
)


def lexical_value(token, previous):
    word = token.strip()
    lower = word.lower()
    if lower == 'soon':
        if word == 'soon' and not token.startswith(' '):
            return 1.8
        if word == 'Soon':
            return 4.65 if token.startswith(' ') else 4.0
        return 3.55 if previous == 'as' else 4.3
    for value, words in ADVERBS:
        if lower in words:
            if word in {'Eventually', 'Suddenly', 'Easily'}:
                value += 0.4
            return value
    for value, words in TRANSITIONS:
        if word in words:
            return value
    if word == '放':
        return -6.9
    if word in {'开放', '開放', '解放', '放在', '放到'}:
        return -3.35
    if word in {'发放', '放进', '放入', '放置', '放出', '放过',
                '放开', '存放', '投放'}:
        return -2.5
    if '放' in word:
        if word == '放弃':
            return -0.45
        return -1.25
    if word in {'发', '發', '防'}:
        return -0.7
    if word == '방':
        return -1.7

    # Release words also occur after punctuation in code and file paths.
    stem = lower.lstrip('._/-')
    if stem in {'release', 'released', 'releases', 'releasing', 'openness'}:
        return -0.9
    if lower in {'liberation', 'liberated', 'liberate'}:
        if lower == 'liberation':
            return -2.1 if word == 'Liberation' else -1.45
        return -0.5
    if lower == 'playback':
        return -1.15
    if lower == 'placement':
        return -0.3 if token == 'placement' else -1.1
    if lower in {'placed', 'posted'}:
        return -1.8 if word == 'Posted' else -0.25
    if word.endswith('><'):
        return -1.7 if word == '><' else -1.2
    if word == '.git':
        return 0.78
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = lexical_value(token, previous)
    # Byte-fragment tokens sometimes finish a Chinese character. Recognize
    # the completed 放 in the jointly decoded prefix, not its replacement glyph.
    if '\ufffd' in token and prefix.text_prefixes[-1].endswith('放'):
        value = -8.0
    return (doc, token.strip().lower()), value

programs.haiku:
"""Layer 0, MLP down-projection component 1205.

What it does: it reads the word being processed (not its context, mostly) and writes a signal
that is large and positive on adverbs of timing and speed, and large and negative on the
Chinese character 放 and the words built on it (put, place, open, release, let go), plus the
English "release" family.

  * "soon", its Chinese equivalents 遂 / 于是 ("thereupon"):          about +4.3
  * speed/suddenness/promptness: shortly, quickly, suddenly, promptly, easily,
    eventually, 很快, 不久, 便, 终于, 迅速, 尽快, 立刻, 顿时:          about +1.7
  * milder manner/sequence adverbs: successfully, immediately,
    gradually, slowly, instantly, 马上, 立即, 突然:                    about +0.7
  * bare 放 (put/release):                                             about -7
  * compounds with 放 (放在, 开放, 发放, 投放, 释放, 放入 ...):         about -2.5
  * release / released / releases / placement / liberation:           about -1
  * the blog byline "Posted":                                          about -1.8
Everything else: 0. Stateless: each prediction uses only the newest token.
"""
READS = ()

SOON = {"soon", "遂", "于是"}
PROMPT = {"shortly", "quickly", "suddenly", "seamlessly", "promptly", "easily", "swiftly",
          "eventually", "很快", "不久", "便", "很快就", "从此", "尽快", "迅速", "终于", "立刻",
          "顿时", "就会"}
MILD = {"successfully", "immediately", "subsequently", "readily", "rapidly", "instantly",
        "gradually", "slowly", "smoothly", "efficiently", "effortlessly", "突然", "忽然", "逐渐",
        "渐渐", "马上", "立即", "赶快", "从而", "竟然"}
RELEASE_EN = {"release", "released", "releases", "releasing", "unleash", "unleashed",
              "liberated", "liberation", "placement"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    if w in SOON:
        v = 4.3
    elif w in PROMPT:
        v = 1.7
    elif w in MILD:
        v = 0.7
    elif s.strip() == "放":
        v = -7.0
    elif "放" in s:
        v = -2.5
    elif w in RELEASE_EN:
        v = -1.0
    elif s.strip() == "Posted":
        v = -1.8
    else:
        v = 0.0
    return carry, float(v)

programs.luna:
"""A sparse word-level sketch: near-term/easy-progress terms versus release/open cues."""

READS = ()

SOON = {"soon"}
EASY_OR_PROGRESSIVE = {"quickly", "easily", "eventually"}
TIMING_AND_TRANSITION_ADVERBS = {
    "immediately", "subsequently", "suddenly", "gradually", "slowly",
    "smoothly", "successfully", "duly", "rapidly", "efficiently",
    "shortly", "finally", "instead", "thereby", "consequently",
    "быстро", "接著", "居然",
