RELEASE_OR_OPEN_WORDS = {
    "release", "released", "releases", "releasing", "liberation",
    "openness", "posted", "playback",
}
CHINESE_FANG_WORDS = {"放", "开放", "放心", "放弃"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in SOON:
        return None, 3.8
    if token in EASY_OR_PROGRESSIVE:
        return None, 1.2
    if token in TIMING_AND_TRANSITION_ADVERBS:
