programs.sol:
"""A heuristic for closing notation and selected English phrase endings.

Percent notation and isolated closing quotes receive positive predictions.
Quote pairing, whitespace within the span, and the preceding character
adjust their strengths; embedded apostrophes normally stay near zero.
Selected verb-particle pairs have signed predictions, e.g. set/make up is
positive, while serve as and stand out are negative. Other tokens normally
get zero. Quote state resets at newlines and everything resets per document.
The constants approximate training activation averages, not exact responses.
"""
READS = ()


def forms(words):
    return frozenset(words.split())


CREATE = forms('set sets setting make makes made making build builds built building')
COME = forms('come comes came coming')
BRING = forms('bring brings brought bringing')
HOLD = forms('hold holds held holding')
STAND = forms('stand stands stood standing')
FALL = forms('fall falls fell fallen falling')
SERVE = forms('serve serves served serving')
CALL = forms('call calls called calling')
TURN = forms('turn turns turned turning')
PUT = forms('put puts putting')
CUT = forms('cut cuts cutting')


def closing_mark(token, previous, double=0, single=0, double_spaces=0, single_spaces=0):
    last = previous[-1:]
    if '%' in token:
        if token == '%':
            return 1.28 if last.isdigit() else 0.94
        if token.startswith(' ') and token.strip() == '%':
            return 0.82
        if token.startswith('%'):
            if token == '%,':
                return 0.80
            if token == '%\n':
                return 0.67
            if token.endswith('\n\n'):
                return 0.43
            return 0.50
        return 0.45
    if token in {'％', '‰'}:
        return 0.61 if token == '％' else 0.34
    if token in {'"', '”', '»', '」', '』', '’', "'"}:
        if '\n' in previous or not previous:
            return 0.04
        if token in {"'", '’'}:
            if not single:
                return 0.02 if last.isalnum() else -0.02
            if not last.isalnum():
                return 0.30 if token == '’' else 0.06
            if token == '’':
                return 0.77 if last.isascii() else 0.52
            if last.isdigit():
                return 0.32
            if single == 1 or single_spaces >= 5:
                return 0.08
            if len(previous.strip()) == 1:
                return 0.15
            return 0.52 if previous.startswith(' ') else 0.42
        if last.isdigit():
            return 0.53 if token in {'"', '”'} else 0.25
        if last.isalpha():
            if token == '"':
                if not last.isascii():
                    return 0.67 if double else 0.08
                if double == 1:
                    return 0.40
                if not double:
                    return 0.50
                if double_spaces >= 5:
                    return 0.73
                if len(previous.strip()) == 1:
                    return 0.60
                return 1.06 if previous.startswith(' ') else 0.98
            if token == '”':
                return (0.80 if double_spaces >= 5 else 1.21) if last.isascii() else 0.80
            return 0.50
        return 0.22
    if token in {' ”', ' »'}:
        return 0.45
    if token.startswith(('”', '」', '』', '»')):
        return 0.28
    if token in {'》', '″'}:
        return 0.21 if token == '》' else 0.44
    if token == ' percent':
        return 0.47
    if token == ' percentage':
        return 0.18
    return 0.0


def verb_particle(token, previous):
    word = previous.strip().lower()
    particle = token.strip().lower()
    if particle in {'up', 'ups', '-up'}:
        extra = 0.20 if particle == '-up' else 0.0
        if word in CREATE:
            return 0.98 + extra
        if (word in HOLD or word in {
            'hook', 'hooks', 'hooked', 'hooking',
            'start', 'starts', 'started', 'starting',
        }):
            return 0.65 + extra
        if word in PUT or word in {'keep', 'keeps', 'kept', 'keeping'}:
            return 0.57 + extra
        if word in {
            'open', 'opens', 'opened', 'opening',
            'break', 'breaks', 'broke', 'breaking',
        }:
            return 0.50 + extra
        if (word in COME or word in BRING or word in {
            'pick', 'picks', 'picked', 'picking', 'clean', 'grow', 'grew',
        }):
            return 0.30 + extra
        if word in {
            'show', 'shows', 'shown', 'showing',
            'follow', 'follows', 'followed', 'following', 'of', 'to',
        }:
            return -0.15
        return 0.05 + extra
    if particle == 'as':
        if word in SERVE or word in STAND or word in COME:
            return -0.88
        if word in {'act', 'acts', 'acted', 'acting', 'emerge', 'emerges', 'emerged'}:
            return -0.43
    if particle in {'out', '-out'}:
        if word in STAND:
            return -1.18
        if word in TURN:
            return -0.41
        if word in CUT:
            return 0.56
    if particle == 'together':
        if word in BRING:
            return -1.20
        if word in COME or word in PUT or word in HOLD:
            return -0.90
        return -0.11
    if particle in {'back', '-back'}:
        if word in HOLD or word in CUT or word in {'pay', 'pays', 'paid', 'paying'}:
            return 0.76
        if word in {'lay', 'lays', 'laid', 'laying'}:
            return 0.80 if particle == '-back' else 0.58
        if word in COME:
            return 0.46
        if word in PUT:
            return 0.56
        return 0.04
    if particle in {'off', '-off'} and (word in CREATE or word in CUT):
        return 0.58
    if particle in {'under', 'within', 'on', 'into', 'between'} and word in FALL:
        return -0.90 if particle != 'into' else -0.44
    if particle == 'on':
        if word in HOLD or word in CALL or word in {'draw', 'draws', 'drew', 'drawing'}:
            return -0.53
        if (word in PUT or word in {
            'sit', 'sits', 'sat', 'sitting', 'lie', 'lies', 'lay', 'lying',
        }):
            return -0.42
        if word == 'light':
            return -0.60
    if particle == 'with':
        if word in CALL:
            return -0.64
        if word in COME or word in {'filled', 'fill', 'touch'}:
            return -0.40
    if particle == 'to':
        if word in COME or word in BRING:
            return -0.47
        if word in {'rise', 'rises', 'rose', 'rising', 'open', 'opens', 'opened'}:
            return -0.35
    if particle == 'about' and (word in BRING or word in COME):
        return -0.80
    if particle == 'light' and word in {'shed', 'sheds', 'shedding'}:
        return -1.0
    return 0.0


def quote_state(token, previous, state):
    """Track straight/curly quotes; space-opened quotes differ from literals."""
    double, single, double_spaces, single_spaces = state
    for i, char in enumerate(token):
        before = token[i - 1] if i else previous[-1:]
        after = token[i + 1:i + 2]
        if char.isspace():
            double_spaces += bool(double)
            single_spaces += bool(single)
        if char == '“':
            double, double_spaces = 2, 0
        if char == '”':
            double = 0
        if char == '"' and before != "\\":
            if double:
                double, double_spaces = 0, 0
            else:
                double, double_spaces = (2 if before.isspace() else 1), 0
        if char == '‘':
            single, single_spaces = 2, 0
        if char == "'" and before != "\\":
            if before.isalnum():
                if not after.isalpha():
                    single = 0
            elif not after or not after.isspace():
                single, single_spaces = (2 if before.isspace() else 1), 0
        if char == '’' and not after.isalpha():
            single = 0
    if "\n" in token:
        double = single = 0
    return double, single, double_spaces, single_spaces


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, state = '', (0, 0, 0, 0)
    else:
        _, previous, state = carry
    token = prefix.token_strings[-1]
    value = closing_mark(token, previous, *state)
    value += verb_particle(token, previous)
    state = quote_state(token, previous, state)
    return (doc, token, state), float(value)

programs.haiku:
"""Layer-0 MLP down-projection, component 1206.

What it does, in plain terms: a "closing mark" detector. It writes a positive
signal into the residual stream on
  * the percent sign "%" (strongest), and " %" a bit weaker;
  * a closing quotation mark that is glued to a word or number, e.g. the end of
    `"standard"` or `"Ukraine"` (opening quotes after a space or newline stay near zero);
  * the word "percent";
  * the particle "up" in phrasal verbs, strongest after "make" and "set"
    ("set up", "make up"), weaker after other verbs, negative after "show".
Single quotes give a weak signal. Everything else is near zero.
"""

READS = ()

PERCENT = 1.27        # "%"
SPACED_PERCENT = 0.8  # " %"
CLOSE_CURLY = 1.0     # ” after a word
CLOSE_STRAIGHT = 0.8  # " after a word or digit
PERCENT_WORD = 0.45   # " percent"
UP_AFTER_MAKE_SET = 1.05
UP_OTHER = 0.35
SINGLE_QUOTE = 0.1    # '


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if token == "%":
        value = PERCENT
    elif token == " %":
        value = SPACED_PERCENT
    elif token == "”":
        value = CLOSE_CURLY if before[-1:].isalnum() else 0.3
    elif token == '"':
        value = CLOSE_STRAIGHT if before[-1:].isalnum() else 0.05
    elif token == " percent":
        value = PERCENT_WORD
    elif token == " up":
        if before.strip().lower() in ("make", "makes", "making", "set", "sets", "setting"):
            value = UP_AFTER_MAKE_SET
        elif before.strip().lower() in ("show", "shows", "showed", "shown", "by", "of"):
            value = 0.0
        else:
            value = UP_OTHER
    elif token == "'":
        value = SINGLE_QUOTE
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A selective scale/size/extent vocabulary detector.

Scale words dominate, especially after small/large/full.  Size, mass,
scope, and extent vocabulary is weaker.  Base noun spellings in code are usually
weaker than spaced prose.  'Of' after a magnitude noun echoes its response.
The multilingual list names size, scale, range, and degree vocabulary.
Only three preceding token strings are retained, reset at document changes.
Unlisted tokens are zero; this does not detect measurements in general.
"""
READS = ()

SCALE_FORMS = {
    'scale': 2.8, 'scales': 2.05, 'cale': 2.5, 'cales': 1.8,
    'scaled': 1.0, 'caled': 0.95, 'scaling': 0.65, 'scalability': 0.65,
    'scalable': 0.77,
}
EXTENT_WORDS = {
    'scope': 1.1, 'magnitude': 1.1, 'magn': 0.63,
    'mass': 0.52, 'masses': 0.26, 'massive': 0.76,
    'extent': 0.75, 'extensive': 0.68, 'extensively': 0.51,
    'widespread': 1.3, 'rapid': 0.59,
    'small': 0.22, 'smaller': 0.21, 'large': 0.22, 'larger': 0.23,
}
MULTILINGUAL_MAGNITUDE = {
    '规模': 5.4, '規模': 6.1, '大规模': 4.9,
    '规模以上': 2.6, '尺度': 3.35,
    '范围': 1.25, '範': 1.38, '范围内': 0.95,
    '尺寸': 0.82, '大小': 0.52, '程度': 0.63,
    '的程度': 1.03, '一定程度': 0.45, 'サイズ': 0.4,
}


def form(token):
    return token.strip().lstrip('._(-').lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, last_value = (), 0.0
    else:
        previous, last_value = carry[1:]
    token = prefix.token_strings[-1]
    word = form(token)
    spaced = token.startswith(' ')
    before = ''.join(previous).lower().rstrip(' -')
    small = before.endswith(('small', 'smaller'))
    large = before.endswith(('large', 'larger'))
    value = 0.0

    if word in SCALE_FORMS:
        value = SCALE_FORMS[word]
        if word == 'scale':
            if small:
                value = 6.0
            elif large:
                value = 5.3
            elif before.endswith(('full', 'medium', 'global', 'industrial')):
                value = 4.8
            elif before.endswith('initial'):
                value = 1.8
            elif not spaced:
                value = 3.3 if token.startswith('-') else 2.3
                if token.startswith('.'):
                    value = 1.2
    elif word in {'size', 'sizes', 'sized', 'sizing'}:
        value = 0.75 if spaced else 0.34
        if word == 'sizing':
            value = 0.5
        elif word == 'sized':
            value = 0.75
        if (small or large) and word != 'sizing':
            value = 1.5
    elif spaced and word in EXTENT_WORDS:
        value = EXTENT_WORDS[word]
    elif word in {'scope', 'mass', 'magnitude'}:
        value = {'scope': 0.6, 'mass': 0.52, 'magnitude': 0.8}[word]
    elif token in MULTILINGUAL_MAGNITUDE:
        value = MULTILINGUAL_MAGNITUDE[token]
    elif word == 'of' and previous:
        noun = form(previous[-1])
        if noun in {'scale', 'scales', 'scope', 'magnitude', 'extent', 'size', 'sizes'}:
            if noun in {'size', 'sizes'}:
                factor = 0.4
            else:
                factor = 0.7 if noun == 'extent' else 0.6
            value = factor * last_value

    return (doc, (*previous[-2:], token), value), float(value)

"""Selective la/ra spelling detector. Isolated La/la and L/l, katakana
r-row syllables and Korean rieul syllables receive positive responses.
Case, word boundaries and byte splitting change their strength. A few
related Romance articles, English word families and Chinese l-initial
transliteration characters also get positive responses. Everything else is zero.
The strengths are training averages, not a general-purpose l/r detector.
"""
import re

READS = ()
# Token bytes 20 EB: space plus an incomplete Hangul UTF-8 leading byte.
SPACE_HANGUL_LEAD_BYTE = 5140
# Article strengths: lowercase continuation, separated, capitalized.
ARTICLES = {"las": (0.27, 0.53, 0.78), "los": (0.0, 0.30, 0.58),
            "le": (0.0, 0.16, 0.22), "les": (0.0, 0.05, 0.06),
            "el": (0.0, 0.21, 0.12)}

KOREAN_VOWELS = "ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"


def response(s, previous="", split=False):
    w = re.sub(r"^[\s_=/\-()\[\]{<>,:.'\"\\]+", "", s)
    if not w:
        return 0.0
    low = w.lower()
    separated = w != s
    boundary = separated or not previous or not previous[-1].isalpha()
    if low == "la":
        if w == "La":
            return 1.95 if boundary else 1.60
        if w == "LA":
            return 0.87 if separated else 0.51
        return 1.30 if boundary else 0.75
    if low == "l":
        return 0.55 if separated else (0.45 if boundary else 0.27)
    if low in ARTICLES and not w.isupper():
        return ARTICLES[low][2 if w[0].isupper() else int(separated)]
    if low in ("là", "lá", "lä", "lą"):
        return 0.40
    if low.startswith("launch"):
        return 1.58 if low == "launched" else 1.10
    if low in ("run", "runs", "running", "ran") and not w.isupper():
        return {"run": 0.23, "runs": 0.23, "running": 0.57,
                "ran": 0.64 if boundary else 0.35}[low]
    if low in ("range", "ranges", "ranged", "ranging", "rand"):
        return 0.80 if s.startswith(("_", "(")) else 0.35
    if len(w) == 1 and w in "拉兰蘭朗郎":
        return 2.55
    if len(w) == 1 and w in "啦辣蓝藍篮揽喇腊":
        return 1.15
    if len(w) == 1 and w in "龙龍罗羅萝伦倫莱萊赖賴鲁魯卢吕":
        return 0.80
    # Katakana r-row, with stronger responses to byte-fragment completions.
    if split and w in "ラリルレロ":
        return {"ラ": 4.75, "リ": 1.10, "ル": 1.30,
                "レ": 3.80, "ロ": 3.95}[w]
    if w in ("ラ", "ラン"):
        return 2.88
    if w in ("レ", "レイ", "レン"):
        return 1.15
    if w == "ロ":
        return 0.65
    if w in ("ら", "ラー", "ライ", "ブラ"):
        return 0.40
    if w in ("라", "란", "랜", "라는", "이라"):
        return 5.40 if split else 2.90
    if w in ("라고", "이라는", "이라고"):
        return 1.50
    if len(w) == 1 and "가" <= w <= "힣":
        initial, rest = divmod(ord(w) - ord("가"), 588)
        # Unicode syllables enumerate initial, vowel and 28 final forms.
        vowel = KOREAN_VOWELS[rest // 28]
        if initial == 5:  # Korean ㄹ, romanized r/l
            if split:
                return 3.15 if vowel in "ㅓㅔ" else 1.50
            return {"ㅏ": 1.10, "ㅐ": 1.0, "ㅓ": 1.30, "ㅔ": 1.0,
                    "ㅗ": 0.80, "ㅜ": 0.80, "ㅡ": 0.25}.get(vowel, 0.0)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ""
    s = prefix.token_strings[-1]
    if prefix.token_ids[-1] == SPACE_HANGUL_LEAD_BYTE:
        value = 2.05
    else:
        split = "�" in s and bool(previous)
        if split:
            s = prefix.text_prefixes[-1][-1:]
        value = response(s, previous, split)
    return (doc, prefix.token_strings[-1]), float(value)

"""Local English phrase completions, with a four-token memory.

Negative pulses finish make sure, once again/more, think/talk about, and
comparisons intensified by even or a change verb. Result constructions such
as make it clear and get ready are also negative. Concern/worry about is
positive. Additional rules cover motion particles, problem/stance + with,
rights, and Chinese words for further/more. Memory resets at each document;
most token-specific background effects are omitted.
"""
READS = ()
MAKE = {'make', 'makes', 'making', 'made'}
GET = {'get', 'gets', 'getting', 'got', 'gotten'}
BECOME = {'become', 'becomes', 'becoming', 'became'}
CHANGE = GET | BECOME | {'grow', 'grows', 'growing', 'grew', 'grown'}
BRIDGES = {'it', 'them', 'me', 'you', 'this', 'that', 'even', 'much', 'more'}
COMPARATIVES = set((
    'more further better worse easier harder stronger closer '
    'bigger larger smaller older simpler'
).split())
RESULTS = {
    'sure': -2.25, 'clear': -1.49, 'certain': -0.96,
    'possible': -1.35, 'sense': -0.95, 'use': -1.13, 'ready': -0.86,
}
ABOUT = (
    ({'think', 'thinks', 'thinking', 'thought'}, -1.78),
    ({'talk', 'talks', 'talking', 'talked'}, -0.73),
    ({'learn', 'learning', 'learned'}, -1.03),
    ({'bring', 'brings', 'bringing', 'brought', 'come', 'came'}, -1.21),
    ({'concern', 'concerns', 'concerned', 'sorry', 'complaints'}, 1.24),
    ({'worry', 'worried', 'worrying', 'curious'}, 0.79),
    ({'care'}, 0.62), ({'question', 'questions'}, 0.43),
)
PHRASES = {
    'once again': -2.73, 'once more': -2.92,
    'each other': -0.78, 'one another': -0.99, 'any other': -0.19,
    'even though': -0.85, 'be sure': -0.59, 'later on': -1.05,
    "let 's": 0.35, 'let ’s': 0.35,
}
BASE = {'sure': -0.24, 'again': -0.21, 'further': -0.80,
        'more': -0.18, 'worse': -0.71, 'though': -0.09}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else []
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    previous = history[-1] if history else ''
    verb = ''
    for earlier in reversed(history):
        if earlier in MAKE | CHANGE:
            verb = earlier
            break
        if earlier not in BRIDGES:
            break
    value = BASE.get(word, 0.0)
    if word in COMPARATIVES and (raw[:1].isspace() or not history):
        value = BASE.get(word, -0.1)
        if previous == 'even':
            value -= 2.14 if word == 'more' else 1.03
        elif previous == 'much':
            value -= 0.78 if word == 'more' else 0.32
        elif previous in {'bit', 'lot', 'little', 'far'}:
            value -= 0.27
        if verb:
            value -= 1.13
        if word == 'more':
            if previous in {'one', 'times', 'learn', 'learns', 'learning'}:
                value -= 0.75
            elif previous in {'ever', 'increasingly', 'twice'}:
                value -= 1.1
            elif previous in {'be', 'been'}:
                value -= 0.25
            elif previous in {'to', 'for', 'of', 'in'}:
                value = 0.0
    elif word == 'about':
        value = -0.11
        for words, pulse in ABOUT:
            if previous in words:
                value = pulse
                break
        if previous in {'more', 'much'}:
            value = -1.0 if previous == 'more' else -0.3
            for words, pulse in ABOUT:
                if any(x in words for x in history[-3:-1]):
                    value += 0.8 * pulse
                    break
        elif previous == 'is':
            value = -0.29
    elif verb in MAKE and word in RESULTS:
        value = RESULTS[word]
    elif verb in GET and word in {'ready', 'rid', 'married', 'close'}:
        value = -1.12
    elif verb in BECOME and word in {'clear', 'possible', 'apparent', 'evident'}:
        value = -1.28
    elif word in {'on', 'back', 'into', 'in'} and previous in CHANGE | {
        'move', 'moves', 'moving', 'moved', 'come', 'comes', 'coming', 'came'
    }:
        value = {'on': -0.8, 'back': -0.55, 'into': -0.33, 'in': -0.23}[word]
    elif word == 'with' and previous in {
        'issue', 'issues', 'problem', 'problems', 'concern', 'concerns',
        'concerned', 'pleased', 'wrong', 'love', 'made', 'satisfied'
    }:
        value = 0.55
    elif word == 'rights':
        value = 0.32 if previous == 'all' else 0.64
    elif word in {'进一步', '更加'}:
        value = -0.95 if word == '进一步' else -0.5
    value = PHRASES.get(previous + ' ' + word, value)
    return (doc, (history + [word])[-4:]), value

programs.haiku:
"""Layer-0 MLP unit 1211 (down_proj): a "make it X" / "even more" word detector.

The unit is negative on the word that completes a set phrase of degree,
repetition or result, and near zero almost everywhere else:
  - "make sure", "made it possible", "make it clear", "get ready", "make sense",
    "get rid", "getting married": the word that completes "make / become / get"
    (possibly with one object word between, like "it"); strongest for "sure";
  - "even more", "much more", "becoming more": "more" after even / much / a
    verb of becoming; "even worse", "much easier" likewise;
  - "once again": "again" after "once"; "further" nearly always (strongest
    after "even": "even further");
  - "think about", "talk about": "about" after thinking or talking verbs;
  - comparatives such as "worse", "stronger", "easier", "harder": mild negative.
It is mildly positive on "rights" and on "about" after worry/concern words
("concerned about", "worried about").

The program reads only the last two words in the same document, so it is
stateless. Values are in the component's own activation units (about -2 at its
strongest, 0 for most tokens).
"""

READS = ()

MAKE_BECOME_GET = {
    "make", "makes", "made", "making",
    "become", "becomes", "became", "becoming",
    "get", "gets", "got", "getting",
}
OBJECTS = {"it", "this", "that", "them", "me", "myself", "things", "matters", "much"}
THINK_TALK = {"think", "thinking", "thought", "talk", "talks", "talking"}
CONCERN = {"concerned", "concerns", "concern", "worried", "worry", "curious", "questions"}
COMPLEMENT = {  # words that complete "make X" / "get X" phrases
    "sure": -2.3, "more": -1.8, "possible": -1.5, "clear": -1.5,
    "ready": -1.3, "sense": -1.0, "use": -1.1, "back": -0.7,
    "rid": -1.1, "married": -1.0,
}
DEGREE_BEFORE_MORE = {"even": -2.6, "once": -2.5, "much": -0.9}
COMPARATIVE = {"worse": -0.8, "stronger": -0.8, "easier": -0.7, "harder": -0.5, "closer": -0.4}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    prev2 = ""
    docs = prefix.document_ids
    if len(prefix) > 1 and docs[-2] == docs[-1]:
        prev = prefix.token_strings[-2].strip().lower()
        if len(prefix) > 2 and docs[-3] == docs[-1]:
            prev2 = prefix.token_strings[-3].strip().lower()

    value = 0.0
    verb_before = prev in MAKE_BECOME_GET or (prev in OBJECTS and prev2 in MAKE_BECOME_GET)
    if verb_before and word in COMPLEMENT:
        value = COMPLEMENT[word]
    elif word == "more":
        value = DEGREE_BEFORE_MORE.get(prev, -0.1)
    elif word == "again":
        value = -2.8 if prev == "once" else -0.2
    elif word == "further":
        value = -2.0 if prev == "even" else -0.8
    elif word == "sure":
        value = -0.5 if prev == "be" else -0.25
    elif word == "about":
        if prev in THINK_TALK or prev == "more":
            value = -1.2
        elif prev in CONCERN:
            value = 0.5
        else:
            value = -0.2
    elif word == "other":
        value = -0.8 if prev == "each" else 0.0
    elif word == "rights":
        value = 0.8
    elif word in COMPARATIVE:
        value = -1.8 if prev == "even" else COMPARATIVE[word]
    return carry, float(value)

programs.luna:
"""A lexical approximation to a rare word-sensitive contribution.

The harvested high-impact examples concentrate on comparative words and on
phrases like 'make sure', 'once again', and 'think about'. The program uses
only the current word and a few preceding words, and predicts nothing elsewhere.
"""
READS = ()

COMPARATIVE = {"more", "further", "bigger", "simpler", "other", "first"}
RELATIONAL = {"about", "though", "on", "there"}
DESCRIPTIVE = {"sure", "clear", "ready", "public", "again", "see"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    start = len(prefix.token_ids) - 1
    while start > 0 and prefix.document_ids[start - 1] == doc and start > len(prefix.token_ids) - 9:
        start -= 1
    before = "".join(prefix.token_strings[start:-1]).lower().rstrip()
    prior_word = before.split()[-1] if before.split() else ""

    value = 0.0
    if word in COMPARATIVE:
        value = -0.12
        if prior_word in {"much", "even", "any", "become"}:
            value = -0.40
    elif word in RELATIONAL:
        value = -0.10
        if word == "about" and prior_word in {
            "think", "thinking", "talk", "talking", "brought", "go", "related"
        }:
            value = -0.40
    elif word in DESCRIPTIVE:
        value = -0.12
        if word == "sure" and prior_word in {"make", "be"}:
            value = -0.80
        elif word == "again" and prior_word == "once":
            value = -0.80
        elif word == "see":
            value = 0.15
    return carry, float(value)

programs.sol:
"""Approximate a mixture of short-range lexical responses.

The main positive rules recognize record/communication compounds: config
files, log methods, order details, decision-making and awards received.
Smaller lexical biases favor receiving/filing and CamelCase processing roles,
and oppose efficiency, scheduling, review and illumination vocabulary.
System namespace members are negative. Other tokens are near zero. These
families leave most small token-specific responses unexplained.
"""
import re
READS = ()

RECORDS = set('''config configuration settings log logger order orders request
requests req form record records score grade'''.split())
COMMUNICATION = set('''email mail message msg post posts postal comment comments
report essay news address sign'''.split())
BUSINESS = set('''account accounts payment payments credit card cards bill
registration login password claim claims ballot'''.split())
DETAILS = set('''address body book books box card cards data detail details fee
file files form forms format formatter handler dispatcher header headers
history holder loader manager management number page parser path process
processing processor processors server service services statement storage submission
submissions validation writer reader keeping campaigns engine engines item quantity
section sections line
received payable'''.split())
FUNCTION_WORDS = set('''a an the of in on at to from for by with without as that
this these those and or but if is are was were be been being not no all each
any some his her its their our your my it he she they we you i s ing ed'''.split())
ROOTS = RECORDS | COMMUNICATION | BUSINESS
RECEIVING = set('receive received receiving receives submitted submitting'.split())
FILING = set('filed filing submission submissions fee fees'.split())
EFFICIENCY = set('''efficient efficiency improve improved improving improvement
benefit benefits convenient straightforward simplify simplified'''.split())
SCHEDULING = set('schedule scheduled scheduling upcoming'.split())
REVIEW = set('review reviews baseline trial trials'.split())
LIGHT = set('light lights sunlight lighting'.split())
CODE_ROLES = set('''parser processor formatter handler writer reader loader
builder generator server body dispatcher'''.split())
NEGATIVE_WORDS = EFFICIENCY | SCHEDULING | REVIEW | LIGHT
LOG_METHODS = set('''debug error fatal info infof init new warn warning trace
print printf println d e i v w'''.split())


def response(previous, token):
    match = re.search(r'[A-Z]?[a-z]+$|[A-Z]+$', previous)
    root = match.group().lower() if match else ''
    word = token.strip().lstrip('._-').lower()
    value = -0.001
    if word in RECEIVING | FILING:
        value = 0.14
    if word in NEGATIVE_WORDS:
        value = -0.11
    if word in CODE_ROLES and token[:1].isupper():
        value = 0.14
    if root in ROOTS:
        if word in DETAILS:
            value = 0.45
        elif word.isascii() and word.isalpha() and word not in FUNCTION_WORDS:
            value = 0.12
    if root in {'config', 'configuration', 'settings'} and word in {
        'file', 'files'
    }:
        value = 1.15 if root == 'config' else 0.8
    if root == 'config' and word in {
        'get', 'parse', 'sections', 'loader', 'compiler', 'server', 'format'
    }:
        value = 0.8
    if root in {'log', 'logger'}:
        if word in {'file', 'files', 'format', 'formatter', 'writer'}:
            value = 1.1
        if word == 'book':
            value = 0.7 if previous.startswith('/') else 1.5
        if token.startswith('.') and word in LOG_METHODS:
            value = 0.2 if root == 'logger' else 0.65
            if root == 'log' and word in {'print', 'printf', 'println'}:
                value = 1.0
            elif root == 'log' and token[1:2].isupper():
                value = 0.4
    if root == 'form' and word in {'submission', 'submissions', 'control', 'data'}:
        value = 0.8
    if root in {'account', 'accounts', 'registration', 'payment'} and word in {
        'manager', 'fee', 'processing', 'processor', 'payable', 'receivable'
    }:
        value = 0.95
    if root in {'comment', 'comments', 'message'} and word in {
        'section', 'board', 'box'
    }:
        value = 0.95
    if root in {'claims', 'decisions', 'changes'} and word == 'made':
        value = 0.55
    if root in {'order', 'orders'} and word in DETAILS | {'placed', 'issued'}:
        value = 1.0
    if root in {'decision', 'policy', 'rule', 'grant'} and word in {
        'making', 'maker', 'makers'
    }:
        value = 0.95 if word == 'making' else 0.7
    if root in {'award', 'medal'} and word in {'received', 'winning'}:
        value = 0.92 if root == 'award' else 0.4
    if root in {'email', 'mail'} and word == '@example':
        value = 0.68
    if root == 'system' and token.startswith('.'):
        value = {'text': -0.87, 'net': -1.1, 'data': -1.0, 'io': -0.7,
                 'string': -0.48, 'collections': -0.3, 'linq': -0.34
                 }.get(word, -0.14)
    if root == 'systematic' and word == 'review':
        value = -0.53
    if root in {'claim', 'sign'} and word in {
        'ant', 'ants', 'atories', 'posted', 'language'
    }:
        value = 0.52
    if root == 'search' and word in {'engine', 'engines'}:
        value = 0.7
    if root in {'request', 'requests', 'req'} and word in {
        'get', 'getparameter', 'body', 'handler', 'dispatcher', 'form',
        'files', 'method'
    }:
        value = 0.8
    if previous in {'申请', '申請'} and token in {'书', '書'}:
        value = 1.4  # application letter or form
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(response(previous, token))

programs.luna:
"""Guess a small positive signal on document and web-app vocabulary.

The harvested strong positions often name files, writing, messages, readers,
forms, or web and software data; ordinary tokens get zero.
"""
READS = ()

DOCUMENT_WORDS = frozenset({
    "file", "book", "essay", "writing", "reader", "title", "post",
