programs.sol:
"""Predict a case-transition pulse rather than a topic or word meaning.

Short lowercase pieces after a capital or acronym get a positive pulse that
shrinks with length, whitespace, and non-ASCII spelling. Smaller rules cover
short-letter sequences, uppercase-after-uppercase suppression, document starts,
and conversation delimiters. The last decoded letter repairs split characters;
NUL separators are skipped when remembering the preceding text token.
"""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    if "\ufffd" in token:
        last = prefix.text_prefixes[-1][-1:]
        if last.isalpha():
            token = (" " if token[0].isspace() else "") + last
    if token == "\x00":
        return (doc, previous), -0.095
    new_carry = (doc, token)
    s, p = token.strip(), previous.strip()
    value = 0.0

    if token == "<|im_start|>":
        return new_carry, 0.185 if previous else -0.084
    if token == "<think>":
        return new_carry, 0.25
    if token in ("</tool_call>", "</tool_response>", "<tool_response>"):
        return new_carry, -0.11
    if not s:
        return new_carry, value

    spaced = token[0].isspace()
    n = len(s)
    if p and p[-1].isupper():
        if s[0].islower():
            if spaced:
                value = 0.53 if s.isascii() else 0.27
                if n > 1:
                    value = 0.07 / (n - 1)
            else:
                value = (1.30, 0.80, 0.36, 0.11, 0.055)[min(n, 5) - 1]
                if not s.isascii():
                    name = unicodedata.name(s[0], "")
                    value *= 0.72 if "CYRILLIC" in name else 0.54
        elif s[0].isupper() and sum(c.isalpha() for c in p) == 1:
            value = -0.13 if spaced or n >= 3 else -0.035
        elif not spaced and n <= 3 and s[-1].islower():
            # A separator attached to a letter, e.g. a subscript or hyphen.
            value = 0.35 if n == 2 else 0.15
    elif not spaced and s[0].islower():
        if n == 1:
            if p.istitle() and len(p) > 1:
                value = 0.20 if len(p) == 2 else 0.03
            elif len(p) == 1 and p.islower():
                name = unicodedata.name(s, "")
                value = 0.25 if "CYRILLIC" in name else 0.11
            elif (p and p[-1].islower()
                  and sum(c.isalpha() for c in p) == 1):
                value = 0.30
        elif len(p) == 1 and p.islower():
            value = 0.05 if n == 2 else -0.03 if n <= 4 else -0.06
    if not previous and n == 1 and s.isupper():
        value = -0.16
    return new_carry, value

programs.luna:
"""Give a small negative estimate for monetary and percentage cues.

Dollar signs are the clearest cue. Percent notation and a few amount words
also get a smaller estimate. These cues predict the direction, not the exact
activation, so the estimates are conservative.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    low = word.lower()

    if word == "$":
        return carry, -0.8 if token.startswith(" ") else -1.0
    if word == r"\$":
        return carry, -1.2
    if word == "%":
        return carry, -0.26
    if word == "$$":
        return carry, -0.18
    if low in ("percent", "percentage"):
        return carry, -0.3
    if low in ("amount", "money", "monetary", "revenue"):
        return carry, -0.14
    return carry, 0.0

programs.sol:
"""Approximate a punctuation/structural-boundary response.

Unspaced punctuation is negative when it follows a line break, indentation,
or other symbols rather than a word. Periods ending ordinary prose lines
are slightly positive. Chat/tool tags and line-initial paths are special
structural boundaries. Most ordinary words are left at zero.
"""
READS = ()

TAGS = {
    '<|im_start|>': -1.53, '<|im_end|>': 0.10,
    '<tool_call>': -1.93, '</tool_call>': -1.96,
    '<tool_response>': -2.36, '</tool_response>': -2.30,
    '<think>': -1.27, '</think>': -1.40,
    '<|endoftext|>': 0.0,
}


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    initial = carry is None or carry[0] != doc
    previous = '' if initial else carry[1]
    newline = previous.endswith('\n')
    space = bool(previous) and previous[-1].isspace()
    symbols = bool(previous) and not any(c.isalnum() for c in previous)
    value = 0.0
    strength = first = ordinary = 0.0

    if token in TAGS:
        value = 0.0 if initial else TAGS[token]
    elif token.startswith(('/test', '/workspace')):
        path_strength = 2.60 if token.startswith('/test') else 1.43
        value = -path_strength if newline else -1.47 if space else -0.10
    elif token == './':
        value = -1.35 if newline else -0.40
    elif token == '.git':
        value = -1.58 if newline else -0.59 if space else -0.24
    elif token.startswith('.') and any(c.isalnum() for c in token):
        value = -2.86 if newline else -1.28 if space else 0.0
    elif token.strip() == '.' and token.startswith('.'):
        breaks = min(token.count('\n'), 2)
        strength = (3.36, 2.20, 1.87)[breaks]
        first = (-0.82, -1.31, -0.71)[breaks]
        ordinary = (0.013, 0.126, 0.043)[breaks]
    elif token.startswith(('}', ')', ']')):
        brace = token.startswith('}')
        if '\n' in token:
            strength = 0.52 if brace else 1.56
            ordinary = 0.035
        else:
            strength = 1.16 if brace else 2.66
    elif token.startswith((',', '，', '、')):
        strength, first, ordinary = 2.99, -0.78, 0.018
    elif token.startswith((':', '：')):
        strength, first, ordinary = 1.99, -0.68, 0.016
    elif token.startswith('。'):
        strength, first = 2.18, -0.85
    elif token.startswith(('?', '!', '？', '！')):
        strength, first = 1.18, -0.31
    elif newline or space:
        if token.startswith('_'):
            value = -0.90
        elif token.startswith(('<', '>')):
            value = -0.32
        elif token.startswith(('+', '*', '|')):
            value = -0.20
        elif token.startswith(('(', '[', '{')):
            value = -0.12
        elif token.startswith('/') and any(c.isalnum() for c in token):
            value = -1.84

    # Boundary penalties are weaker after spaces or other punctuation.
    if strength:
        if initial:
            value = first
        elif newline:
            value = -strength
        elif space:
            value = -strength * (0.85 if '\n' in token else 0.75)
        elif symbols:
            value = -strength * (0.07 if '\n' in token else 0.25)
        else:
            value = ordinary
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 1215.

Strongly negative on two kinds of structural tokens:
1. Chat/tool markup: <tool_call>, </tool_call>, <tool_response>, </tool_response>
   (about -2), <think>, </think> (about -1.3), and <|im_start|> opening a turn (about
   -1.5; ~0 right after <|endoftext|>, i.e. at a document's start).
2. A file or directory name that begins a line, such as a listing entry: a dot-name
   ('.git', '.github', '.docker') or a slash-name ('/testbed', '/workspace'), about -2
   (the strength varies by name). The same names mid-line (e.g. 'tests/test') stay near 0.
Everything else is near 0.
"""

READS = ()

MARKUP = {
    "<tool_call>": -1.9, "</tool_call>": -1.9,
    "<tool_response>": -2.4, "</tool_response>": -2.4,
    "<think>": -1.3, "</think>": -1.4,
}
NAME_STRENGTH = {".github": -3.5, "/test": -2.6, ".git": -1.6, "/workspace": -1.4}
DEFAULT_NAME = -2.2


def is_name(tok):
    """A dot-name or slash-name: '.' or '/' followed by letters only."""
    body = tok[1:]
    return tok[:1] in (".", "/") and len(body) > 0 and body.isalpha() and body.isascii()


def step(carry, prefix, upstream):
    s = prefix.token_strings
    tok = s[-1]
    prev = s[-2] if len(s) > 1 else "<|endoftext|>"
    if tok in MARKUP:
        return None, MARKUP[tok]
    if tok == "<|im_start|>":
        return None, 0.0 if prev == "<|endoftext|>" else -1.5
    if is_name(tok) and prev.endswith("\n"):
        return None, NAME_STRENGTH.get(tok, DEFAULT_NAME)
    return None, 0.0
